    candidate = text
    # MariaDB prepends a legacy "5.5.5-" compatibility prefix for old client handshakes;
    # strip it so the real version is parsed, not the fake 5.5.5.
    if candidate.startswith("5.5.5-"):
        candidate = candidate[len("5.5.5-"):]
    match = re.search(r"(\d+)\.(\d+)\.(\d+)", candidate)
    if match:
        return flavor, (int(match.group(1)), int(match.group(2)), int(match.group(3)))
    return flavor, (0, 0, 0)


