class UserDelegate(BaseDelegate):
    """Async Direct SQL delegate for User"""

    TABLE = "User"
    PK_FIELDS = USER_PK_FIELDS
    PK_SELECTOR = USER_PK_SELECTOR
    UNIQUE_SELECTORS = USER_UNIQUE_SELECTORS
    FIELDS = USER_FIELDS
    FIELD_TO_COLUMN = USER_FIELD_TO_COLUMN
    COLUMN_TO_FIELD = USER_COLUMN_TO_FIELD
    NUMERIC_FIELDS = USER_NUMERIC_FIELDS
    INT_FIELDS = ["roleId"]
    INT_FIELDS_SET: FrozenSet[str] = frozenset(INT_FIELDS)
    DECIMAL_FIELDS = USER_DECIMAL_FIELDS
    DECIMAL_FIELDS_SET: FrozenSet[str] = frozenset(DECIMAL_FIELDS)
    DATETIME_FIELDS = USER_DATETIME_FIELDS
    UPDATED_AT_FIELDS = USER_UPDATED_AT_FIELDS
    JSON_FIELDS = USER_JSON_FIELDS
    SCALAR_LIST_FIELDS = USER_SCALAR_LIST_FIELDS
    SCALAR_LIST_FIELD_TYPES = USER_SCALAR_LIST_FIELD_TYPES
    ENUM_FIELDS = USER_ENUM_FIELDS
    SCALAR_LIST_ENUM_FIELDS = USER_SCALAR_LIST_ENUM_FIELDS
    RELATION_CONFIGS: Dict[str, Dict[str, Any]] = {
        "userRole": {"model": "UserRole", "kind": "owned", "local_fields": ["roleId"], "remote_fields": ["id"], "can_disconnect": True}
    }

    def _row_to_model(self, row: Any, columns: List[str]) -> User:
        """Convert row to model instance"""
        if isinstance(row, dict):
            if self.HAS_COLUMN_ALIASES:
                data = {
                    self._logical_field(str(key)): value
                    for key, value in row.items()
                }
            else:
                # No @map'd columns: DB keys already equal logical field names, so a
                # plain copy avoids a per-key method call and str() on the hot path.
                data = dict(row)
        else:
            data = dict(zip(columns, row))
        # Convert datetime strings back to datetime objects
        if data.get("emailVerified") and isinstance(data["emailVerified"], str):
            try:
                data["emailVerified"] = datetime.fromisoformat(data["emailVerified"])
            except (TypeError, ValueError):
                pass
        if data.get("createdAt") and isinstance(data["createdAt"], str):
            try:
                data["createdAt"] = datetime.fromisoformat(data["createdAt"])
            except (TypeError, ValueError):
                pass
        if data.get("updatedAt") and isinstance(data["updatedAt"], str):
            try:
                data["updatedAt"] = datetime.fromisoformat(data["updatedAt"])
            except (TypeError, ValueError):
                pass




        # Convert enum string values back to enum instances
        for enum_field, enum_class in self.ENUM_FIELDS.items():
            if enum_field in data and data[enum_field] is not None:
                try:
                    data[enum_field] = enum_class(data[enum_field])
                except (ValueError, KeyError):
                    pass  # Keep original value if conversion fails
        return User(**{k: v for k, v in data.items() if k in self.FIELDS_SET})

    def _relation_filter_requires_python_evaluation(
        self,
        relation_name: str,
        condition: Any,
    ) -> bool:
        config = self.RELATION_CONFIGS.get(relation_name)
        if config is None or not isinstance(condition, Mapping):
            return True

        related_delegate = self._get_delegate(cast(str, config["model"]))
        if related_delegate is None:
            return True

        # SQL generation currently uses table names as references. Self-relations
        # need aliases to avoid ambiguous identifiers, so keep those on the safe
        # Python path until alias-aware SQL generation lands.
        if related_delegate.TABLE == self.TABLE:
            return True

        kind = cast(str, config["kind"])
        condition_dict = dict(condition)

        if kind in ("m2m", "inverse_many"):
            for operator, nested_where in condition_dict.items():
                if operator not in ("some", "none", "every"):
                    return True
                if not isinstance(nested_where, Mapping):
                    return True
                if related_delegate._where_requires_python_evaluation(
                    cast(Mapping[str, Any], nested_where)
                ):
                    return True
            return False

        relation_operators = [
            operator for operator in condition_dict.keys() if operator in ("is", "isNot")
        ]
        if relation_operators:
            for operator, nested_where in condition_dict.items():
                if operator not in ("is", "isNot"):
                    return True
                if nested_where is None:
                    continue
                if not isinstance(nested_where, Mapping):
                    return True
                if related_delegate._where_requires_python_evaluation(
                    cast(Mapping[str, Any], nested_where)
                ):
                    return True
            return False

        return related_delegate._where_requires_python_evaluation(condition_dict)

    def _build_relation_exists_sql(
        self,
        relation_name: str,
        config: Mapping[str, Any],
        nested_where: Optional[Mapping[str, Any]],
        param_offset: int,
        negate_nested: bool = False,
    ) -> Tuple[str, List[Any], int]:
        related_delegate = self._get_delegate(cast(str, config["model"]))
        if related_delegate is None:
            raise ValueError(f"Unknown relation delegate for '{relation_name}'")

        kind = cast(str, config["kind"])
        params: List[Any] = []
        idx = param_offset

        if kind == "m2m":
            join_table = cast(str, config["join_table"])
            local_column = cast(str, config["local_column"])
            remote_column = cast(str, config["remote_column"])
            local_pk_field = cast(str, config["local_pk_field"])
            remote_pk_field = cast(str, config["remote_pk_field"])
            conditions = [
                f"{SQLBuilder.column_ref(local_column, join_table)} = {SQLBuilder.column_ref(self._db_column(local_pk_field), self.TABLE)}"
            ]

            join_sql = (
                f"{SQLBuilder.quote_identifier(join_table)} "
                f"INNER JOIN {SQLBuilder.quote_identifier(related_delegate.TABLE)} "
                f"ON {SQLBuilder.column_ref(related_delegate._db_column(remote_pk_field), related_delegate.TABLE)} = "
                f"{SQLBuilder.column_ref(remote_column, join_table)}"
            )
        else:
            local_fields = cast(List[str], config["local_fields"])
            remote_fields = cast(List[str], config["remote_fields"])
            conditions = [
                f"{SQLBuilder.column_ref(related_delegate._db_column(remote_field), related_delegate.TABLE)} = {SQLBuilder.column_ref(self._db_column(local_field), self.TABLE)}"
                for local_field, remote_field in zip(local_fields, remote_fields)
            ]
            join_sql = SQLBuilder.quote_identifier(related_delegate.TABLE)

        if nested_where:
            nested_sql, nested_params, idx = related_delegate._build_sql_where(
                cast(Mapping[str, Any], nested_where),
                related_delegate.TABLE,
                idx,
            )
            if nested_sql:
                conditions.append(f"NOT ({nested_sql})" if negate_nested else f"({nested_sql})")
                params.extend(nested_params)

        where_sql = " AND ".join(conditions) if conditions else "1 = 1"
        return f"EXISTS (SELECT 1 FROM {join_sql} WHERE {where_sql})", params, idx

    def _build_relation_filter_sql(
        self,
        relation_name: str,
        condition: Any,
        param_offset: int,
    ) -> Tuple[str, List[Any], int]:
        config = self.RELATION_CONFIGS.get(relation_name)
        if config is None or not isinstance(condition, Mapping):
            raise ValueError(f"Unsupported relation filter for '{relation_name}'")

        kind = cast(str, config["kind"])
        condition_dict = dict(condition)
        clauses: List[str] = []
        params: List[Any] = []
        idx = param_offset

        if kind in ("m2m", "inverse_many"):
            for operator, nested_where in condition_dict.items():
                nested_mapping = cast(Mapping[str, Any], nested_where)
                if operator == "every" and not nested_mapping:
                    continue
                exists_sql, exists_params, idx = self._build_relation_exists_sql(
                    relation_name,
                    config,
                    nested_mapping,
                    idx,
                    negate_nested=operator == "every",
                )
                if operator == "some":
                    clauses.append(exists_sql)
                elif operator in ("none", "every"):
                    clauses.append(f"NOT ({exists_sql})")
                else:
                    raise ValueError(
                        f"Unsupported list relation filter operation '{operator}' for relation '{relation_name}'"
                    )
                params.extend(exists_params)
            return " AND ".join(clauses), params, idx

        relation_operators = [
            operator for operator in condition_dict.keys() if operator in ("is", "isNot")
        ]
        if relation_operators:
            for operator, nested_where in condition_dict.items():
                if operator not in ("is", "isNot"):
                    raise ValueError(
                        f"Unsupported to-one relation filter operation '{operator}' for relation '{relation_name}'"
                    )
                is_null_check = nested_where is None
                nested_mapping = None if is_null_check else cast(Mapping[str, Any], nested_where)
                exists_sql, exists_params, idx = self._build_relation_exists_sql(
                    relation_name,
                    config,
                    nested_mapping,
                    idx,
                )
                # A null target flips the meaning: {is: null} matches rows with NO related
                # record (NOT EXISTS), {isNot: null} matches rows that HAVE one (EXISTS).
                # With a nested filter it is the usual {is} -> EXISTS, {isNot} -> NOT EXISTS.
                if is_null_check:
                    clauses.append(f"NOT ({exists_sql})" if operator == "is" else exists_sql)
                else:
                    clauses.append(exists_sql if operator == "is" else f"NOT ({exists_sql})")
                params.extend(exists_params)
            return " AND ".join(clauses), params, idx

        exists_sql, exists_params, idx = self._build_relation_exists_sql(
            relation_name,
            config,
            condition_dict,
            idx,
        )
        return exists_sql, exists_params, idx

    def _build_sql_where(
        self,
        where: Optional[Mapping[str, Any]],
        table: str = "",
        param_offset: int = 0,
    ) -> Tuple[str, List[Any], int]:
        if not where:
            return "", [], param_offset

        conditions: List[str] = []
        params: List[Any] = []
        idx = param_offset

        for key, value in dict(where).items():
            if key == "AND":
                sub_conditions: List[str] = []
                for clause in ensure_list(value):
                    if not isinstance(clause, Mapping):
                        continue
                    sql, nested_params, idx = self._build_sql_where(
                        cast(Mapping[str, Any], clause),
                        table,
                        idx,
                    )
                    if sql:
                        sub_conditions.append(f"({sql})")
                        params.extend(nested_params)
                if sub_conditions:
                    conditions.append(f"({' AND '.join(sub_conditions)})")
                continue

            if key == "OR":
                or_clauses = [
                    clause for clause in ensure_list(value) if isinstance(clause, Mapping)
                ]
                if not or_clauses:
                    # Prisma: OR over an empty list matches no rows (the Python
                    # fallback in _record_matches_where already behaves this way).
                    conditions.append("1 = 0")
                    continue
                sub_conditions = []
                for clause in or_clauses:
                    sql, nested_params, idx = self._build_sql_where(
                        cast(Mapping[str, Any], clause),
                        table,
                        idx,
                    )
                    if sql:
                        sub_conditions.append(f"({sql})")
                        params.extend(nested_params)
                if sub_conditions:
                    conditions.append(f"({' OR '.join(sub_conditions)})")
                continue

            if key == "NOT":
                for clause in ensure_list(value):
                    if not isinstance(clause, Mapping):
                        continue
                    sql, nested_params, idx = self._build_sql_where(
                        cast(Mapping[str, Any], clause),
                        table,
                        idx,
                    )
                    if sql:
                        conditions.append(f"NOT ({sql})")
                        params.extend(nested_params)
                continue

            if key in self.RELATION_CONFIGS:
                sql, relation_params, idx = self._build_relation_filter_sql(key, value, idx)
                if sql:
                    conditions.append(sql)
                    params.extend(relation_params)
                continue

            if key in self.JSON_FIELDS_SET:
                sql, json_params, idx = SQLBuilder.build_json_filter(
                    key,
                    cast(Mapping[str, Any], value),
                    table,
                    idx,
                    self.FIELD_TO_COLUMN,
                )
                if sql:
                    conditions.append(sql)
                    params.extend(json_params)
                continue

            sql, scalar_params, idx = SQLBuilder.build_where(
                {key: value},
                table,
                idx,
                self.FIELD_TO_COLUMN,
                self.SCALAR_LIST_FIELDS,
            )
            if sql:
                conditions.append(sql)
                params.extend(scalar_params)

        return " AND ".join(conditions), params, idx

    def _merge_relation_filter_load_options(
        self,
        target: Dict[str, Any],
        source: Optional[Mapping[str, Any]],
    ) -> None:
        if not source:
            return

        for relation_name, incoming in dict(source).items():
            existing = target.get(relation_name)
            if isinstance(existing, Mapping) and isinstance(incoming, Mapping):
                merged = dict(existing)
                merged_include = dict(cast(Mapping[str, Any], merged.get("include") or {}))
                incoming_include = cast(Mapping[str, Any], incoming.get("include") or {})
                self._merge_relation_filter_load_options(merged_include, incoming_include)
                if merged_include:
                    merged["include"] = merged_include
                target[relation_name] = merged
                continue

            if existing is True and isinstance(incoming, Mapping):
                target[relation_name] = dict(incoming)
                continue

            if isinstance(existing, Mapping) and incoming is True:
                continue

            target[relation_name] = dict(incoming) if isinstance(incoming, Mapping) else True

    def _build_relation_filter_load_options(
        self,
        where: Optional[Mapping[str, Any]],
    ) -> Optional[Dict[str, Any]]:
        if not where:
            return None

        load_options: Dict[str, Any] = {}

        for key, value in dict(where).items():
            if key in ("AND", "OR", "NOT"):
                for clause in ensure_list(value):
                    if isinstance(clause, Mapping):
                        nested_options = self._build_relation_filter_load_options(
                            cast(Mapping[str, Any], clause)
                        )
                        self._merge_relation_filter_load_options(load_options, nested_options)
                continue

            config = self.RELATION_CONFIGS.get(key)
            if config is None:
                continue

            option: Any = True
            if isinstance(value, Mapping):
                related_delegate = self._get_delegate(cast(str, config["model"]))
                nested_loads: Dict[str, Any] = {}
                if cast(str, config["kind"]) in ("m2m", "inverse_many"):
                    for operator in ("some", "none", "every"):
                        nested_where = value.get(operator)
                        if isinstance(nested_where, Mapping):
                            self._merge_relation_filter_load_options(
                                nested_loads,
                                related_delegate._build_relation_filter_load_options(
                                    cast(Mapping[str, Any], nested_where)
                                ),
                            )
                else:
                    has_relation_operator = False
                    for operator in ("is", "isNot"):
                        if operator not in value:
                            continue
                        has_relation_operator = True
                        nested_where = value.get(operator)
                        if isinstance(nested_where, Mapping):
                            self._merge_relation_filter_load_options(
                                nested_loads,
                                related_delegate._build_relation_filter_load_options(
                                    cast(Mapping[str, Any], nested_where)
                                ),
                            )
                    if not has_relation_operator:
                        self._merge_relation_filter_load_options(
                            nested_loads,
                            related_delegate._build_relation_filter_load_options(
                                cast(Mapping[str, Any], value)
                            ),
                        )

                if nested_loads:
                    option = {"include": nested_loads}

            self._merge_relation_filter_load_options(load_options, {key: option})

        return load_options or None

    def _sql_pushdown_where(self, where: Optional[Mapping[str, Any]]) -> Optional[Dict[str, Any]]:
        """Return the SQL-expressible subset of a Python-evaluated where, as an AND.

        Used when the full filter needs Python evaluation: each top-level conjunct of
        the where (implicit AND of keys, flattened through explicit AND nodes) that is
        individually SQL-expressible is pushed to the query so fewer rows are scanned,
        and Python still applies the complete filter afterward for exactness.
        Narrowing by a subset of AND conditions can only return a superset of the final
        rows, so this is always sound. An OR or NOT node is pushed only when fully
        expressible; an OR with a Python disjunct cannot be partially pushed.
        Returns None when no conjunct is pushable (a true full-table scan).
        """
        if not where:
            return None

        conjuncts: List[Dict[str, Any]] = []

        def collect(node: Mapping[str, Any]) -> None:
            for key, value in dict(node).items():
                if key == "AND":
                    for clause in ensure_list(value):
                        if isinstance(clause, Mapping):
                            collect(cast(Mapping[str, Any], clause))
                    continue
                candidate: Dict[str, Any] = {key: value}
                if not self._where_requires_python_evaluation(candidate):
                    conjuncts.append(candidate)

        collect(where)

        if not conjuncts:
            return None
        if len(conjuncts) == 1:
            return conjuncts[0]
        return {"AND": conjuncts}

    def _where_requires_python_evaluation(
        self,
        where: Optional[Mapping[str, Any]],
    ) -> bool:
        if not where:
            return False

        for key, value in dict(where).items():
            if key in ("AND", "OR", "NOT"):
                if any(
                    self._where_requires_python_evaluation(cast(Mapping[str, Any], clause))
                    for clause in ensure_list(value)
                    if isinstance(clause, Mapping)
                ):
                    return True
                continue

            if key in self.RELATION_CONFIGS:
                if self._relation_filter_requires_python_evaluation(key, value):
                    return True
                continue

            if key in self.JSON_FIELDS_SET:
                if not SQLBuilder.can_build_json_filter(value):
                    return True
                continue

            if key in self.SCALAR_LIST_FIELDS_SET and SQLBuilder.PROVIDER != "postgresql":
                return True

        return False

    def _matches_relation_filter(
        self,
        relation_name: str,
        relation_value: Any,
        condition: Any,
    ) -> bool:
        config = self.RELATION_CONFIGS.get(relation_name)
        if config is None:
            raise ValueError(f"Unknown relation filter: {relation_name}")

        if not isinstance(condition, Mapping):
            raise ValueError(f"Relation filter '{relation_name}' expects a mapping value")

        delegate = self._get_delegate(cast(str, config["model"]))
        relation_kind = cast(str, config["kind"])

        if relation_kind in ("m2m", "inverse_many"):
            items = relation_value if isinstance(relation_value, list) else []
            for operation, expected in dict(condition).items():
                if operation not in ("some", "none", "every"):
                    raise ValueError(
                        f"Unsupported list relation filter operation '{operation}' for relation '{relation_name}'"
                    )
                if not isinstance(expected, Mapping):
                    raise ValueError(
                        f"List relation filter '{relation_name}.{operation}' expects a mapping value"
                    )

                nested_where = cast(Mapping[str, Any], expected)
                if operation == "some":
                    if not any(delegate._record_matches_where(item, nested_where) for item in items):
                        return False
                    continue
                if operation == "none":
                    if any(delegate._record_matches_where(item, nested_where) for item in items):
                        return False
                    continue
                if not all(delegate._record_matches_where(item, nested_where) for item in items):
                    return False

            return True

        if not condition:
            return relation_value is not None

        relation_operators = [
            operation for operation in dict(condition).keys() if operation in ("is", "isNot")
        ]
        if relation_operators:
            for operation, expected in dict(condition).items():
                if operation not in ("is", "isNot"):
                    raise ValueError(
                        f"Unsupported to-one relation filter operation '{operation}' for relation '{relation_name}'"
                    )

                if operation == "is":
                    if expected is None:
                        if relation_value is not None:
                            return False
                        continue
                    if not isinstance(expected, Mapping):
                        raise ValueError(
                            f"To-one relation filter '{relation_name}.is' expects a mapping value or None"
                        )
                    if relation_value is None or not delegate._record_matches_where(
                        relation_value,
                        cast(Mapping[str, Any], expected),
                    ):
                        return False
                    continue

                if expected is None:
                    if relation_value is None:
                        return False
                    continue
                if not isinstance(expected, Mapping):
                    raise ValueError(
                        f"To-one relation filter '{relation_name}.isNot' expects a mapping value or None"
                    )
                if relation_value is not None and delegate._record_matches_where(
                    relation_value,
                    cast(Mapping[str, Any], expected),
                ):
                    return False

            return True

        if relation_value is None:
            return False

        return delegate._record_matches_where(
            relation_value,
            cast(Mapping[str, Any], condition),
        )

    def _record_matches_where(self, record: Any, where: Optional[Mapping[str, Any]]) -> bool:
        if not where:
            return True

        for key, value in dict(where).items():
            if key == "AND":
                clauses = [clause for clause in ensure_list(value) if isinstance(clause, Mapping)]
                if not all(
                    self._record_matches_where(record, cast(Mapping[str, Any], clause))
                    for clause in clauses
                ):
                    return False
                continue

            if key == "OR":
                clauses = [clause for clause in ensure_list(value) if isinstance(clause, Mapping)]
                if not clauses or not any(
                    self._record_matches_where(record, cast(Mapping[str, Any], clause))
                    for clause in clauses
                ):
                    return False
                continue

            if key == "NOT":
                clauses = [clause for clause in ensure_list(value) if isinstance(clause, Mapping)]
                if any(
                    self._record_matches_where(record, cast(Mapping[str, Any], clause))
                    for clause in clauses
                ):
                    return False
                continue

            if key in self.RELATION_CONFIGS:
                if not self._matches_relation_filter(key, getattr(record, key, None), value):
                    return False
                continue

            if key in self.JSON_FIELDS_SET:
                if not matches_json_filter_value(get_source_value(record, key), value):
                    return False
                continue

            if key in self.SCALAR_LIST_FIELDS_SET:
                if not matches_scalar_list_filter_value(get_source_value(record, key), value):
                    return False
                continue

            if not matches_scalar_filter_value(get_source_value(record, key), value):
                return False

        return True

    def _record_matches_unique(self, record: Any, where: Mapping[str, Any]) -> bool:
        return all(get_source_value(record, field) == value for field, value in dict(where).items())

    def _apply_distinct_results(
        self,
        records: List[User],
        distinct: Optional[List[str]] = None,
    ) -> List[User]:
        if not distinct:
            return records

        seen: Set[Tuple[Any, ...]] = set()
        unique_records: List[User] = []
        for record in records:
            key = tuple(get_source_value(record, field) for field in distinct)
            if key in seen:
                continue
            seen.add(key)
            unique_records.append(record)

        return unique_records

    def _apply_window_results(
        self,
        records: List[User],
        cursor: Optional[UserWhereUniqueInput] = None,
        skip: Optional[int] = None,
        take: Optional[int] = None,
    ) -> List[User]:
        offset = skip or 0

        if take == 0:
            return []

        if cursor:
            normalized_cursor = self._normalize_unique_where(cast(Mapping[str, Any], cursor))
            cursor_index: Optional[int] = None
            for index, record in enumerate(records):
                if self._record_matches_unique(record, normalized_cursor):
                    cursor_index = index
                    break

            if cursor_index is None:
                return []

            if take is not None and take < 0:
                end_index = cursor_index + 1 - offset
                if end_index <= 0:
                    return []
                start_index = max(0, end_index + take)
                return records[start_index:end_index]

            start_index = max(0, cursor_index + offset)
            if take is None:
                return records[start_index:]
            return records[start_index:start_index + take]

        if take is not None and take < 0:
            end_index = len(records) - offset
            if end_index <= 0:
                return []
            start_index = max(0, end_index + take)
            return records[start_index:end_index]

        if offset:
            records = records[offset:]

        if take is not None:
            return records[:take]

        return records

    def _order_by_is_sql_expressible(self, order_by: Optional[Any]) -> bool:
        """True only for plain scalar asc/desc (optionally with sort/nulls) order clauses.

        Relation/aggregate ordering (e.g. _count or nested relation order) is not
        SQL-expressible here, so those force the Python fallback path.
        """
        if not order_by:
            return True
        for clause in ensure_list(order_by):
            if not isinstance(clause, Mapping):
                return False
            for field, direction in clause.items():
                if not isinstance(field, str) or field.startswith("_") or field not in self.FIELDS_SET:
                    return False
                if isinstance(direction, str):
                    continue
                if isinstance(direction, Mapping):
                    if set(direction.keys()) - {"sort", "nulls"}:
                        return False
                    continue
                return False
        return True

    async def _relation_window_pk_filter(
        self,
        base_where: Mapping[str, Any],
        fk_fields: List[str],
        nested_order: Optional[Any],
        nested_skip: Optional[int],
        nested_take: Optional[int],
    ) -> Optional[Dict[str, Any]]:
        """Push a per-parent take/skip window into SQL for a to-many include.

        Returns a primary-key where fragment selecting exactly the windowed child
        rows (one window per parent via ROW_NUMBER), an empty dict when the window
        matches nothing, or None to signal the caller to keep the existing
        fetch-all + Python window path. Only simple, fully SQL-expressible cases are
        pushed down; everything else falls back so behavior is unchanged.
        """
        if SQLBuilder.PROVIDER == "mysql" and not get_db_capabilities().supports_window_functions:
            return None  # ROW_NUMBER needs MySQL 8.0+ / MariaDB 10.2+; older servers keep the Python window

        offset = int(nested_skip) if nested_skip else 0
        take_limit = int(nested_take) if nested_take is not None else None
        if offset < 0:
            return None
        if take_limit is not None and take_limit < 0:
            return None  # negative take (last N) stays in Python
        if take_limit is None and not offset:
            return None  # nothing to window
        if not self.PK_FIELDS or not fk_fields:
            return None
        if self._where_requires_python_evaluation(base_where):
            return None
        if not self._order_by_is_sql_expressible(nested_order):
            return None

        where_sql, where_params, _ = self._build_sql_where(dict(base_where), "", 0)

        pk_columns = [self._db_column(f) for f in self.PK_FIELDS]
        fk_columns = [self._db_column(f) for f in fk_fields]
        select_cols = ", ".join(SQLBuilder.quote_identifier(c) for c in pk_columns)
        partition_sql = ", ".join(SQLBuilder.quote_identifier(c) for c in fk_columns)
        order_sql = (
            SQLBuilder.build_order_by(nested_order, field_map=self.FIELD_TO_COLUMN)
            if nested_order
            else ""
        )
        if not order_sql:
            order_sql = "ORDER BY " + ", ".join(SQLBuilder.quote_identifier(c) for c in pk_columns)

        inner = (
            f"SELECT {select_cols}, "
            f"ROW_NUMBER() OVER (PARTITION BY {partition_sql} {order_sql}) AS _pp_rn "
            f"FROM {SQLBuilder.quote_identifier(self.TABLE)}"
        )
        if where_sql:
            inner += f" WHERE {where_sql}"

        sql = f"SELECT {select_cols} FROM ({inner}) AS _pp_win WHERE _pp_rn > {offset}"
        if take_limit is not None:
            sql += f" AND _pp_rn <= {offset + take_limit}"

        conn = await self._get_conn()
        rows = await fetch_dict_rows(conn, sql, where_params, list(self.PK_FIELDS))
        if not rows:
            return {}

        # The hydrate step binds one (or one-per-PK-column) placeholder per windowed row.
        # If that would exceed the variable limit, fall back to the bounded fetch-all +
        # Python window path instead of emitting an oversized IN/OR list.
        if len(rows) * max(1, len(self.PK_FIELDS)) > _MAX_SQL_VARS:
            return None

        if len(self.PK_FIELDS) == 1:
            field = self.PK_FIELDS[0]
            column = self._db_column(field)
            return {field: {"in_": [row.get(column) for row in rows]}}

        conditions: List[Dict[str, Any]] = []
        for row in rows:
            conditions.append({field: row.get(self._db_column(field)) for field in self.PK_FIELDS})
        return {"OR": conditions}

    async def _load_relation_counts(
        self,
        records: List[User],
        count_requests: Dict[str, Any],
    ) -> None:
        if not records or not count_requests:
            return

        if len(records) > _MAX_SQL_VARS:
            # Chunk parents so a single grouped-count query never binds more than
            # _MAX_SQL_VARS placeholders. Batches are disjoint parent sets, so each
            # writes counts onto its own records.
            for _batch in _chunk(records):
                await self._load_relation_counts(_batch, count_requests)
            return

        conn = await self._get_conn()  # noqa: F841 -- used only by generated count strategies
        handled_count_requests: Set[str] = set()

        remaining_count_requests = {
            relation_name: option
            for relation_name, option in count_requests.items()
            if relation_name not in handled_count_requests
        }
        if not remaining_count_requests:
            return

        count_include = {relation_name: option for relation_name, option in remaining_count_requests.items()}
        await self._load_relations(records, cast(Any, count_include))

        for record in records:
            count_data = dict(record._count or {})
            for relation_name in remaining_count_requests.keys():
                relation_value = getattr(record, relation_name, None)
                if isinstance(relation_value, list):
                    count_data[relation_name] = len(relation_value)
                else:
                    count_data[relation_name] = 1 if relation_value is not None else 0
            record._count = count_data

    def _generate_defaults(self, data_dict: Dict[str, Any]) -> Dict[str, Any]:
        """Generate default values for ID and timestamp fields"""
        if "id" not in data_dict:
            data_dict["id"] = generate_cuid()
        if "createdAt" not in data_dict:
            data_dict["createdAt"] = get_datetime_value(SQLBuilder.PROVIDER)
        if "updatedAt" not in data_dict:
            data_dict["updatedAt"] = get_datetime_value(SQLBuilder.PROVIDER)
        return data_dict

    async def _load_relations(
        self,
        records: List[User],
        include: Optional[UserInclude] = None,
    ) -> None:
        """Load relations for records based on include dict"""
        if not include or not records:
            return

        if len(records) > _MAX_SQL_VARS:
            # Chunk parents so the IN / OR / join lists built per relation never bind
            # more than _MAX_SQL_VARS placeholders. Batches are disjoint parent sets,
            # so each batch loads relations onto its own records independently.
            for _batch in _chunk(records):
                await self._load_relations(_batch, include)
            return

        conn = await self._get_conn()  # noqa: F841 -- used only by generated relation strategies

        # Load userRole relation
        inc_userRole = include.get("userRole")
        if inc_userRole:
            delegate = self._get_delegate("UserRole")
            nested_include = None
            nested_select = None
            nested_omit = None
            nested_where = None
            nested_order = None
            nested_take = None
            nested_skip = None
            nested_distinct = None
            nested_cursor = None

            if isinstance(inc_userRole, dict):
                nested_include = inc_userRole.get("include")
                nested_select = inc_userRole.get("select")
                nested_omit = inc_userRole.get("omit")
                nested_where = inc_userRole.get("where")
                nested_order = inc_userRole.get("orderBy")  # noqa: F841 -- relation-shape dependent
                nested_take = inc_userRole.get("take")  # noqa: F841 -- relation-shape dependent
                nested_skip = inc_userRole.get("skip")  # noqa: F841 -- relation-shape dependent
                nested_distinct = inc_userRole.get("distinct")
                nested_cursor = inc_userRole.get("cursor")

            local_keys = [
                key
                for key in (
                    self._identity_for_fields(record, ["roleId"])
                    for record in records
                )
                if key is not None
            ]
            unique_local_keys = list(dict.fromkeys(local_keys))

            if unique_local_keys:
                if len(unique_local_keys[0]) == 1:
                    base_where: Dict[str, Any] = {
                        "id": {"in_": [key_values[0] for key_values in unique_local_keys]}
                    }
                else:
                    base_conditions: List[Dict[str, Any]] = []
                    for key_values in unique_local_keys:
                        condition = {
                            "id": key_values[0],
                        }
                        base_conditions.append(condition)

                    base_where = {"OR": base_conditions}
                if nested_where:
                    base_where = {"AND": [base_where, nested_where]}

                related_select = augment_relation_select(nested_select, ["id"])
                related = await delegate.find_many(
                    where=base_where,
                    select=related_select,
                    omit=nested_omit,
                    include=nested_include,
                    distinct=nested_distinct,
                    cursor=nested_cursor,
                )
                restore_relation_select(related, nested_select)

                by_key: Dict[Tuple[Any, ...], Any] = {}
                for rel_rec in related:
                    rel_key = delegate._identity_for_fields(
                        rel_rec,
                        ["id"],
                    )
                    if rel_key is not None:
                        by_key[rel_key] = rel_rec

                for rec in records:
                    local_key = self._identity_for_fields(
                        rec,
                        ["roleId"],
                    )
                    rec.userRole = by_key.get(local_key) if local_key is not None else None

    async def find_many(
        self,
        where: Optional[UserWhereInput] = None,
        select: Optional[UserSelect] = None,
        omit: Optional[UserOmit] = None,
        include: Optional[UserInclude] = None,
        order_by: Optional[Union[List[UserOrderBy], UserOrderBy]] = None,
        skip: Optional[int] = None,
        take: Optional[int] = None,
        distinct: Optional[List[str]] = None,
        cursor: Optional[UserWhereUniqueInput] = None,
    ) -> List[User]:
        """Find multiple records with include support"""
        validate_projection_options(select, omit, include)
        conn = await self._get_conn()

        select_dict: Optional[SelectDict] = cast(SelectDict, select) if select else None
        omit_dict: Optional[SelectDict] = cast(SelectDict, omit) if omit else None
        relation_load_options = self._build_relation_load_options(select, include)
        where_requires_python_evaluation = self._where_requires_python_evaluation(where)
        relation_filter_load_options = (
            self._build_relation_filter_load_options(where)
            if where_requires_python_evaluation
            else None
        )
        count_requests = self._extract_count_requests(select, include)
        needs_full_row = bool(
            where_requires_python_evaluation
            or relation_load_options
            or relation_filter_load_options
            or count_requests
        )
        cols_sql, selected_fields = self._build_row_select(
            select_dict,
            omit_dict,
            needs_full_row,
            can_narrow=not where_requires_python_evaluation and not relation_filter_load_options,
        )

        sql = f'SELECT {cols_sql} FROM {SQLBuilder.quote_identifier(self.TABLE)}'

        params: List[Any] = []
        param_idx = 0
        has_where_clause = False

        if where and not where_requires_python_evaluation:
            where_sql, where_params, param_idx = self._build_sql_where(dict(where), "", param_idx)
            if where_sql:
                sql += f" WHERE {where_sql}"
                params.extend(where_params)
                has_where_clause = True
        elif where and where_requires_python_evaluation:
            # The full filter is not SQL-expressible, but we can still push down the
            # SQL-expressible conjuncts so the database returns fewer rows; Python then
            # applies the complete filter below for exactness. Only a where with no
            # pushable conjunct degrades to an actual full-table scan.
            partial_where = self._sql_pushdown_where(where)
            if partial_where:
                where_sql, where_params, param_idx = self._build_sql_where(dict(partial_where), "", param_idx)
                if where_sql:
                    sql += f" WHERE {where_sql}"
                    params.extend(where_params)
                    has_where_clause = True
            else:
                _warn_full_scan("User", "where filter: " + ", ".join(sorted(str(k) for k in dict(where).keys())))

        # SQL-side cursor window: anchor the query at the cursor row with a
        # lexicographic order comparison so only the requested page is fetched,
        # instead of scanning every matching row to locate the cursor in Python.
        # Requires an explicit SQL-expressible order_by; other shapes keep the
        # Python windowing path below.
        cursor_plan: Optional[Dict[str, Any]] = None
        if (
            cursor is not None
            and order_by
            and not distinct
            and not where_requires_python_evaluation
        ):
            cursor_plan = await self._build_cursor_window_plan(cursor, order_by, take, skip)
            if cursor_plan is not None and cursor_plan.get("empty"):
                return []

        if cursor_plan is not None:
            comparison_clauses = cast(List[Tuple[str, bool]], cursor_plan["comparison_clauses"])
            comparison_sql, comparison_params, param_idx = self._build_cursor_comparison_sql(
                comparison_clauses,
                cast(List[Any], cursor_plan["cursor_values"]),
                param_idx,
            )
            sql += (" AND " if has_where_clause else " WHERE ") + comparison_sql
            params.extend(comparison_params)
            order_parts = [
                f"{SQLBuilder.column_ref(self._db_column(field))} {'DESC' if descending else 'ASC'}"
                for field, descending in comparison_clauses
            ]
            sql += " ORDER BY " + ", ".join(order_parts)
        elif order_by:
            if not self._order_by_is_sql_expressible(order_by):
                # Prisma supports relation-field and relation-_count ordering; this
                # client does not yet. Raise instead of emitting broken SQL that
                # references the relation name as a column.
                raise PrismaClientValidationError(
                    "Unsupported order_by: only scalar model fields ordered "
                    "asc/desc (optionally with {sort, nulls}) are supported; "
                    "relation and aggregate ordering are not implemented."
                )
            sql += " " + SQLBuilder.build_order_by(order_by, field_map=self.FIELD_TO_COLUMN)

        apply_sql_window = (
            cursor_plan is None
            and not where_requires_python_evaluation
            and cursor is None
            and not distinct
            and (take is None or take >= 0)
        )
        if cursor_plan is not None:
            plan_take = cast(Optional[int], cursor_plan["take"])
            plan_offset = cast(int, cursor_plan["offset"])
            plan_limit = abs(plan_take) if plan_take is not None else None
            if plan_limit is not None:
                sql += f" LIMIT {plan_limit}"
            elif plan_offset:
                if SQLBuilder.PROVIDER == "sqlite":
                    sql += " LIMIT -1"
                elif SQLBuilder.PROVIDER == "mysql":
                    sql += " LIMIT 18446744073709551615"
            if plan_offset:
                sql += f" OFFSET {plan_offset}"
        elif apply_sql_window and take is not None:
            sql += f" LIMIT {int(take)}"
        elif apply_sql_window and skip:
            # SQLite/MySQL reject OFFSET without LIMIT; emit the provider's
            # "unbounded" limit so skip-only queries stay valid SQL.
            if SQLBuilder.PROVIDER == "sqlite":
                sql += " LIMIT -1"
            elif SQLBuilder.PROVIDER == "mysql":
                sql += " LIMIT 18446744073709551615"
        if apply_sql_window and skip:
            sql += f" OFFSET {int(skip)}"

        rows = await fetch_dict_rows(conn, sql, params, selected_fields)
        results = [self._row_to_model(row, selected_fields) for row in rows]
        if cursor_plan is not None and cast(bool, cursor_plan["reverse"]):
            # Negative take fetched in reversed order; restore the requested order.
            results.reverse()

        if where_requires_python_evaluation:
            if relation_filter_load_options:
                await self._load_relations(results, cast(Any, relation_filter_load_options))
            results = [
                record
                for record in results
                if self._record_matches_where(record, cast(Mapping[str, Any], where))
            ]

        if distinct:
            results = self._apply_distinct_results(results, distinct)

        if not apply_sql_window and cursor_plan is None:
            results = self._apply_window_results(results, cursor, skip, take)

        # Apply query options and load relations
        for rec in results:
            self._apply_query_options(rec, select, omit, include)

        if relation_load_options:
            await self._load_relations(results, cast(Any, relation_load_options))

        if count_requests:
            await self._load_relation_counts(results, count_requests)

        return results

    async def find_unique(
        self,
        where: UserWhereUniqueInput,
        select: Optional[UserSelect] = None,
        omit: Optional[UserOmit] = None,
        include: Optional[UserInclude] = None,
    ) -> Optional[User]:
        """Find unique record with include support"""
        validate_projection_options(select, omit, include)
        conn = await self._get_conn()

        select_dict: Optional[SelectDict] = cast(SelectDict, select) if select else None
        omit_dict: Optional[SelectDict] = cast(SelectDict, omit) if omit else None
        relation_load_options = self._build_relation_load_options(select, include)
        count_requests = self._extract_count_requests(select, include)
        needs_full_row = bool(relation_load_options or count_requests)
        cols_sql, selected_fields = self._build_row_select(
            select_dict,
            omit_dict,
            needs_full_row,
            can_narrow=True,
        )
        sql = f'SELECT {cols_sql} FROM {SQLBuilder.quote_identifier(self.TABLE)}'

        normalized_where = self._normalize_unique_where(where)
        where_sql, params, _ = SQLBuilder.build_where(
            normalized_where,
            field_map=self.FIELD_TO_COLUMN,
            scalar_list_fields=self.SCALAR_LIST_FIELDS,
        )
        if where_sql:
            sql += f" WHERE {where_sql}"
        sql += " LIMIT 1"

        row = await fetch_dict_row(conn, sql, params, selected_fields)
        if not row:
            return None

        result = self._row_to_model(row, selected_fields)
        self._apply_query_options(result, select, omit, include)

        if relation_load_options:
            await self._load_relations([result], cast(Any, relation_load_options))

        if count_requests:
            await self._load_relation_counts([result], count_requests)

        return result

    async def find_unique_or_throw(
        self,
        where: UserWhereUniqueInput,
        select: Optional[UserSelect] = None,
        omit: Optional[UserOmit] = None,
        include: Optional[UserInclude] = None,
    ) -> User:
        """Find unique or raise error"""
        result = await self.find_unique(where, select, omit, include)
        if result is None:
            raise RecordNotFoundError(f"User not found: {where}")
        return result

    async def find_first(
        self,
        where: Optional[UserWhereInput] = None,
        select: Optional[UserSelect] = None,
        omit: Optional[UserOmit] = None,
        include: Optional[UserInclude] = None,
        order_by: Optional[Union[List[UserOrderBy], UserOrderBy]] = None,
        skip: Optional[int] = None,
        distinct: Optional[List[str]] = None,
        cursor: Optional[UserWhereUniqueInput] = None,
    ) -> Optional[User]:
        """Find first matching record"""
        results = await self.find_many(
            where=where, select=select, omit=omit, include=include,
            order_by=order_by, skip=skip, take=1, distinct=distinct, cursor=cursor
        )
        return results[0] if results else None

    async def find_first_or_throw(
        self,
        where: Optional[UserWhereInput] = None,
        select: Optional[UserSelect] = None,
        omit: Optional[UserOmit] = None,
        include: Optional[UserInclude] = None,
        order_by: Optional[Union[List[UserOrderBy], UserOrderBy]] = None,
        skip: Optional[int] = None,
    ) -> User:
        """Find first or raise error"""
        result = await self.find_first(where, select, omit, include, order_by, skip)
        if result is None:
            raise RecordNotFoundError("User not found")
        return result

    async def create(
        self,
        data: UserCreateInput,
        select: Optional[UserSelect] = None,
        omit: Optional[UserOmit] = None,
        include: Optional[UserInclude] = None,
    ) -> User:
        """Create a new record"""
        validate_projection_options(select, omit, include)
        conn = await self._get_conn()

        data_dict = dict(data)
        relation_writes = self._extract_relation_writes(data_dict)
        if relation_writes and not self._is_in_transaction():
            async with self._transaction_scope():
                return await self.create(data, select=select, omit=omit, include=include)
        if "id" not in data_dict:
            data_dict["id"] = generate_cuid()
        if "createdAt" not in data_dict:
            data_dict["createdAt"] = get_datetime_value(SQLBuilder.PROVIDER)
        if "updatedAt" not in data_dict:
            data_dict["updatedAt"] = get_datetime_value(SQLBuilder.PROVIDER)

        await self._apply_pre_write_relations(data_dict, relation_writes)
        data_dict = self._prepare_create_data(data_dict)

        fields = [field for field in self.FIELDS if field in data_dict]
        db_fields = [self._db_column(field) for field in fields]
        values = [data_dict[k] for k in fields]
        pk_field = self.PK_FIELDS[0] if len(self.PK_FIELDS) == 1 else None
        pk_value = data_dict.get(pk_field) if pk_field else None
        db_pk_field = self._db_column(pk_field) if pk_field else None

        supports_create_returning = (
            SQLBuilder.PROVIDER in ("postgresql", "sqlite")
            or get_db_capabilities().supports_insert_returning
        )
        if supports_create_returning and fields:
            # PostgreSQL, SQLite 3.35+, and MariaDB 10.5+: hydrate the created row
            # straight from INSERT ... RETURNING, saving the extra SELECT
            # round-trip the lastrowid path needs below.
            returning_sql, selected_fields = SQLBuilder.build_select(
                self.TABLE,
                self.FIELDS,
                None,
                None,
                field_map=self.FIELD_TO_COLUMN,
            )
            returned_rows = await execute_bulk_insert_returning(
                conn,
                self.TABLE,
                db_fields,
                [tuple(values)],
                returning_sql,
                False,
                self._commit_if_needed,
            )
            if not returned_rows:
                raise RecordNotFoundError("Failed to create User")
            stored_record = self._row_to_model(returned_rows[0], selected_fields)
        else:
            pk_value = await execute_insert_query(
                conn,
                self.TABLE,
                db_fields,
                values,
                db_pk_field,
                pk_value,
                self._commit_if_needed,
            )

            if pk_field is not None and pk_value is not None:
                data_dict[pk_field] = pk_value

            created_where = cast(UserWhereUniqueInput, self._build_primary_where(data_dict))
            stored_record = await self.find_unique(created_where)
            if stored_record is None:
                raise RecordNotFoundError("Failed to create User")

        created_where = cast(UserWhereUniqueInput, self._build_primary_where(stored_record))
        await self._apply_post_write_relations(stored_record, relation_writes)
        if not (select or omit or include):
            return stored_record

        # Scalar-only projections need no relation loads, so the freshly
        # hydrated row can be projected in place without another SELECT.
        relation_load_options = self._build_relation_load_options(select, include)
        count_requests = self._extract_count_requests(select, include)
        if not relation_load_options and not count_requests:
            return self._apply_query_options(stored_record, select, omit, include)

        result = await self.find_unique(created_where, select=select, omit=omit, include=include)
        if result is None:
            raise RecordNotFoundError("Failed to load User after create")
        return result

    async def create_many(
        self,
        data: List[UserCreateInput],
        skip_duplicates: bool = False,
    ) -> Dict[str, int]:
        """Create multiple records using batch insert"""
        if not data:
            return {"count": 0}

        conn = await self._get_conn()

        prepared_rows: List[Dict[str, Any]] = []
        for item in data:
            row = dict(item)
            row = self._generate_defaults(row)
            row = self._prepare_create_data(row)
            prepared_rows.append(row)

        if not prepared_rows:
            return {"count": 0}

        rows_by_shape: Dict[Tuple[str, ...], List[Dict[str, Any]]] = {}
        for row in prepared_rows:
            shape = tuple(field for field in self.FIELDS if field in row)
            rows_by_shape.setdefault(shape, []).append(row)

        count = 0
        for field_shape, rows_for_shape in rows_by_shape.items():
            fields = list(field_shape)
            db_fields = [self._db_column(field) for field in fields]
            values_list = [tuple(row.get(f) for f in fields) for row in rows_for_shape]
            count += await execute_bulk_insert_count(
                conn,
                self.TABLE,
                db_fields,
                values_list,
                skip_duplicates,
            )

        await self._commit_if_needed(conn)
        return {"count": count}

    async def create_many_and_return(
        self,
        data: Union[List[UserCreateInput], UserCreateInput],
        select: Optional[UserSelect] = None,
        omit: Optional[UserOmit] = None,
        include: Optional[UserInclude] = None,
        skip_duplicates: bool = False,
    ) -> List[User]:
        """Create multiple records and return the stored rows"""
        validate_projection_options(select, omit, include)
        if SQLBuilder.PROVIDER == "mysql":
            raise NotImplementedError(
                "Prisma createManyAndReturn is not supported by the MySQL connector. "
                "Use create_many, or explicit create calls inside a transaction when "
                "returned rows are required."
            )
        if SQLBuilder.PROVIDER == "sqlite" and skip_duplicates:
            raise NotImplementedError(
                "Prisma createManyAndReturn does not support skipDuplicates on SQLite."
            )

        raw_items = ensure_list(data)
        if not raw_items:
            return []

        for item in raw_items:
            if not isinstance(item, Mapping):
                raise ValueError("create_many_and_return expects mapping payloads")

        has_relation_writes = any(
            key in self.RELATION_CONFIGS
            for item in raw_items
            for key in cast(Mapping[str, Any], item).keys()
        )
        if has_relation_writes:
            raise PrismaClientValidationError(
                "Nested relation writes are not supported in createManyAndReturn."
            )

        prepared_rows: List[Dict[str, Any]] = []
        for item in raw_items:
            row = self._generate_defaults(dict(cast(Mapping[str, Any], item)))
            row = self._prepare_create_data(row)
            prepared_rows.append(row)

        field_shapes = [
            tuple(key for key in row.keys() if key in self.FIELDS_SET)
            for row in prepared_rows
        ]
        can_use_bulk_return = bool(field_shapes) and all(bool(shape) for shape in field_shapes)

        if can_use_bulk_return:
            conn = await self._get_conn()
            returning_sql, selected_fields = SQLBuilder.build_select(
                self.TABLE,
                self.FIELDS,
                cast(Optional[SelectDict], select),
                cast(Optional[SelectDict], omit),
                field_map=self.FIELD_TO_COLUMN,
            )
            rows: List[Any] = []
            rows_by_shape: Dict[Tuple[str, ...], List[Dict[str, Any]]] = {}
            for shape, row in zip(field_shapes, prepared_rows):
                rows_by_shape.setdefault(shape, []).append(row)

            async with self._transaction_scope():
                for shape, shaped_rows in rows_by_shape.items():
                    fields = list(shape)
                    db_fields = [self._db_column(field) for field in fields]
                    values_list = [
                        tuple(row.get(field) for field in fields)
                        for row in shaped_rows
                    ]
                    rows.extend(
                        await execute_bulk_insert_returning(
                            conn,
                            self.TABLE,
                            db_fields,
                            values_list,
                            returning_sql,
                            skip_duplicates,
                            self._commit_if_needed,
                        )
                    )

            results = [
                self._apply_query_options(
                    self._row_to_model(row, selected_fields),
                    select=select,
                    omit=omit,
                    include=include,
                )
                for row in rows
            ]
            if include:
                relation_load_options = self._build_relation_load_options(None, include)
                if relation_load_options:
                    await self._load_relations(results, cast(Any, relation_load_options))
            return results

        created_records: List[User] = []
        for item in raw_items:
            created_records.append(
                await self.create(
                    cast(UserCreateInput, dict(item)),
                    select=select,
                    omit=omit,
                    include=include,
                )
            )

        return created_records

    async def _find_relation_records_for_write(
        self,
        delegate: Any,
        relation_name: str,
        config: Dict[str, Any],
        record: Any,
        where: Optional[Mapping[str, Any]] = None,
    ) -> List[Any]:
        kind = cast(str, config["kind"])
        if kind == "m2m":
            local_value = get_source_value(record, cast(str, config["local_pk_field"]))
            if local_value is None:
                return []

            # Read the linked ids straight from the join table instead of
            # hydrating every related row through an include only to re-query
            # the same rows with the caller's filter.
            conn = await self._get_conn()
            remote_column = cast(str, config["remote_column"])
            join_sql = (
                f'SELECT {SQLBuilder.quote_identifier(remote_column)} '
                f'FROM {SQLBuilder.quote_identifier(cast(str, config["join_table"]))} '
                f'WHERE {SQLBuilder.quote_identifier(cast(str, config["local_column"]))} = {SQLBuilder.placeholder(0)}'
            )
            join_rows = await fetch_dict_rows(conn, join_sql, [local_value], [remote_column])
            remote_ids = [
                row.get(remote_column)
                for row in join_rows
                if row.get(remote_column) is not None
            ]
            if not remote_ids:
                return []

            remote_pk_field = cast(str, config["remote_pk_field"])
            related_results: List[Any] = []
            for _id_chunk in _chunk(list(dict.fromkeys(remote_ids))):
                combined_where = self._combine_where_clauses(
                    {remote_pk_field: {"in_": _id_chunk}},
                    where,
                )
                if combined_where is None:
                    continue
                related_results.extend(await delegate.find_many(where=combined_where))
            return related_results

        combined_where = self._combine_where_clauses(
            self._build_inverse_parent_where(config, record),
            where,
        )
        if combined_where is None:
            return []
        return await delegate.find_many(where=combined_where)

    async def _apply_pre_write_relations(
        self,
        data_dict: Dict[str, Any],
        relation_writes: Dict[str, Dict[str, Any]],
        existing_record: Optional[Any] = None,
    ) -> None:
        for relation_name, write in relation_writes.items():
            config = self.RELATION_CONFIGS.get(relation_name)
            if not config or cast(str, config["kind"]) != "owned":
                continue

            delegate = self._get_delegate(cast(str, config["model"]))
            local_fields = cast(List[str], config["local_fields"])
            remote_fields = cast(List[str], config["remote_fields"])
            current_related = (
                await self._find_owned_related_record(delegate, config, existing_record)
                if existing_record is not None
                else None
            )

            if write.get("disconnect") is True or (
                "set" in write and write["set"] in (None, [])
            ):
                if not cast(bool, config.get("can_disconnect", False)):
                    raise ValueError(f"Relation '{relation_name}' does not support disconnect")
                for field in local_fields:
                    data_dict[field] = None
                current_related = None

            if write.get("delete"):
                if not cast(bool, config.get("can_disconnect", False)):
                    raise ValueError(f"Relation '{relation_name}' does not support delete")
                if current_related is not None:
                    await delegate.delete(delegate._build_primary_where(current_related))
                for field in local_fields:
                    data_dict[field] = None
                current_related = None

            related_records: List[Any] = []
            if "set" in write and write["set"] not in (None, []):
                related_records = await self._resolve_relation_records(
                    delegate,
                    write["set"],
                    relation_name,
                )
            if "connect" in write:
                related_records = await self._resolve_relation_records(
                    delegate,
                    write["connect"],
                    relation_name,
                )
            if "create" in write:
                related_records = await self._create_relation_records(
                    delegate,
                    write["create"],
                    relation_name,
                )
            if "connectOrCreate" in write:
                related_records = await self._connect_or_create_relation_records(
                    delegate,
                    write["connectOrCreate"],
                    relation_name,
                )

            if "update" in write:
                update_entries = self._normalize_nested_entries(write["update"], relation_name)
                if len(update_entries) > 1:
                    raise ValueError(f"Relation '{relation_name}' only accepts a single update payload")
                if current_related is None:
                    raise RecordNotFoundError(
                        f"Related record for '{relation_name}' was not found for nested update"
                    )

                update_entry = update_entries[0]
                raw_update_data = update_entry.get("data")
                if isinstance(raw_update_data, Mapping):
                    update_data = dict(raw_update_data)
                else:
                    update_data = dict(update_entry)
                current_related = await delegate.update(
                    delegate._build_primary_where(current_related),
                    cast(Dict[str, Any], update_data),
                )
                if current_related is None:
                    raise RecordNotFoundError(
                        f"Failed to update related record for '{relation_name}'"
                    )
                related_records = [current_related]

            if "upsert" in write:
                upsert_entries = self._normalize_nested_entries(write["upsert"], relation_name)
                if len(upsert_entries) > 1:
                    raise ValueError(f"Relation '{relation_name}' only accepts a single upsert payload")

                upsert_entry = upsert_entries[0]
                raw_update_data = upsert_entry.get("update")
                raw_create_data = upsert_entry.get("create")
                if current_related is not None:
                    update_data = dict(raw_update_data) if isinstance(raw_update_data, Mapping) else {}
                    current_related = await delegate.update(
                        delegate._build_primary_where(current_related),
                        cast(Dict[str, Any], update_data),
                    )
                    if current_related is None:
                        raise RecordNotFoundError(
                            f"Failed to upsert related record for '{relation_name}'"
                        )
                    related_records = [current_related]
                else:
                    if not isinstance(raw_create_data, Mapping):
                        raise ValueError(
                            f"Relation '{relation_name}' requires a mapping create payload for upsert"
                        )
                    related_records = await self._create_relation_records(
                        delegate,
                        cast(Dict[str, Any], dict(raw_create_data)),
                        relation_name,
                    )

            self._ensure_singular_relation_write(relation_name, related_records)
            if related_records:
                self._apply_relation_values(
                    data_dict,
                    local_fields,
                    related_records[0],
                    remote_fields,
                )

    async def _apply_post_write_relations(
        self,
        record: Any,
        relation_writes: Dict[str, Dict[str, Any]],
    ) -> None:
        for relation_name, write in relation_writes.items():
            config = self.RELATION_CONFIGS.get(relation_name)
            if not config:
                continue

            relation_config = config
            kind = cast(str, relation_config["kind"])
            if kind == "owned":
                continue

            delegate = self._get_delegate(cast(str, relation_config["model"]))

            if kind == "m2m":
                local_pk_field = cast(str, config["local_pk_field"])
                remote_pk_field = cast(str, config["remote_pk_field"])
                join_table = cast(str, config["join_table"])
                local_column = cast(str, config["local_column"])
                remote_column = cast(str, config["remote_column"])
                local_value = get_source_value(record, local_pk_field)

                if local_value is None:
                    continue

                if "set" in write:
                    await self._clear_m2m_pairs(join_table, local_column, local_value)
                    if write["set"] not in (None, []):
                        set_records = await self._resolve_relation_records(
                            delegate,
                            write["set"],
                            relation_name,
                        )
                        set_pairs = [
                            (local_value, get_source_value(related_record, remote_pk_field))
                            for related_record in set_records
                            if get_source_value(related_record, remote_pk_field) is not None
                        ]
                        await self._connect_m2m_pairs(
                            join_table,
                            local_column,
                            remote_column,
                            set_pairs,
                        )

                create_records = []
                if "create" in write:
                    create_records = await self._create_relation_records(
                        delegate,
                        write["create"],
                        relation_name,
                    )

                connect_records = []
                if "connect" in write:
                    connect_records = await self._resolve_relation_records(
                        delegate,
                        write["connect"],
                        relation_name,
                    )

                connect_or_create_records = []
                if "connectOrCreate" in write:
                    connect_or_create_records = await self._connect_or_create_relation_records(
                        delegate,
                        write["connectOrCreate"],
                        relation_name,
                    )

                connect_pairs = [
                    (local_value, get_source_value(related_record, remote_pk_field))
                    for related_record in create_records + connect_records + connect_or_create_records
                    if get_source_value(related_record, remote_pk_field) is not None
                ]
                await self._connect_m2m_pairs(
                    join_table,
                    local_column,
                    remote_column,
                    connect_pairs,
                )

                if "update" in write:
                    update_entries = self._normalize_nested_entries(write["update"], relation_name)
                    for update_entry in update_entries:
                        where_clause = update_entry.get("where")
                        data_clause = update_entry.get("data")
                        if not isinstance(where_clause, Mapping) or not isinstance(data_clause, Mapping):
                            raise ValueError(
                                f"Relation '{relation_name}' update expects 'where' and 'data' mappings"
                            )

                        target_records = await self._find_relation_records_for_write(
                            delegate,
                            relation_name,
                            config,
                            record,
                            cast(Mapping[str, Any], where_clause),
                        )
                        await self._update_records_bulk(
                            delegate,
                            target_records,
                            cast(Mapping[str, Any], data_clause),
                        )

                if "updateMany" in write:
                    update_many_entries = self._normalize_nested_entries(write["updateMany"], relation_name)
                    for update_entry in update_many_entries:
                        data_clause = update_entry.get("data")
                        where_clause = update_entry.get("where")
                        if not isinstance(data_clause, Mapping):
                            raise ValueError(
                                f"Relation '{relation_name}' updateMany expects a 'data' mapping"
                            )

                        target_records = await self._find_relation_records_for_write(
                            delegate,
                            relation_name,
                            config,
                            record,
                            cast(Optional[Mapping[str, Any]], where_clause)
                            if isinstance(where_clause, Mapping)
                            else None,
                        )
                        await self._update_records_bulk(
                            delegate,
                            target_records,
                            cast(Mapping[str, Any], data_clause),
                        )

                if "upsert" in write:
                    upsert_entries = self._normalize_nested_entries(write["upsert"], relation_name)
                    for upsert_entry in upsert_entries:
                        where_clause = upsert_entry.get("where")
                        update_clause = upsert_entry.get("update")
                        create_clause = upsert_entry.get("create")
                        if not isinstance(where_clause, Mapping):
                            raise ValueError(
                                f"Relation '{relation_name}' upsert expects a 'where' mapping"
                            )

                        target_records = await self._find_relation_records_for_write(
                            delegate,
                            relation_name,
                            config,
                            record,
                            cast(Mapping[str, Any], where_clause),
                        )
                        if target_records:
                            if not isinstance(update_clause, Mapping):
                                raise ValueError(
                                    f"Relation '{relation_name}' upsert expects an 'update' mapping"
                                )
                            await delegate.update(
                                delegate._build_primary_where(target_records[0]),
                                cast(Dict[str, Any], dict(update_clause)),
                            )
                        else:
                            if not isinstance(create_clause, Mapping):
                                raise ValueError(
                                    f"Relation '{relation_name}' upsert expects a 'create' mapping"
                                )
                            created_records = await self._create_relation_records(
                                delegate,
                                cast(Dict[str, Any], dict(create_clause)),
                                relation_name,
                            )
                            create_pairs = [
                                (local_value, get_source_value(related_record, remote_pk_field))
                                for related_record in created_records
                                if get_source_value(related_record, remote_pk_field) is not None
                            ]
                            await self._connect_m2m_pairs(
                                join_table,
                                local_column,
                                remote_column,
                                create_pairs,
                            )

                if write.get("delete") is True:
                    delete_records = await self._find_relation_records_for_write(
                        delegate,
                        relation_name,
                        config,
                        record,
                    )
                    self._ensure_singular_relation_write(relation_name, delete_records)
                    await self._delete_records_bulk(delegate, delete_records)
                elif "delete" in write:
                    delete_entries = self._normalize_nested_entries(write["delete"], relation_name)
                    for delete_entry in delete_entries:
                        delete_records = await self._find_relation_records_for_write(
                            delegate,
                            relation_name,
                            config,
                            record,
                            cast(Mapping[str, Any], delete_entry),
                        )
                        await self._delete_records_bulk(delegate, delete_records)

                if "deleteMany" in write:
                    delete_many_entries = self._normalize_nested_entries(write["deleteMany"], relation_name)
                    for delete_entry in delete_many_entries:
                        delete_records = await self._find_relation_records_for_write(
                            delegate,
                            relation_name,
                            config,
                            record,
                            cast(Optional[Mapping[str, Any]], delete_entry),
                        )
                        await self._delete_records_bulk(delegate, delete_records)

                if write.get("disconnect") is True:
                    await self._clear_m2m_pairs(join_table, local_column, local_value)
                elif "disconnect" in write:
                    disconnect_records = await self._resolve_relation_records(
                        delegate,
                        write["disconnect"],
                        relation_name,
                    )
                    disconnect_pairs = [
                        (local_value, get_source_value(related_record, remote_pk_field))
                        for related_record in disconnect_records
                        if get_source_value(related_record, remote_pk_field) is not None
                    ]
                    await self._disconnect_m2m_pairs(
                        join_table,
                        local_column,
                        remote_column,
                        disconnect_pairs,
                    )

                continue

            if "set" in write:
                await self._clear_inverse_relations(delegate, relation_name, config, record)
                if write["set"] not in (None, []):
                    set_records = await self._resolve_relation_records(
                        delegate,
                        write["set"],
                        relation_name,
                    )
                    await self._attach_inverse_records(
                        delegate,
                        relation_name,
                        config,
                        set_records,
                        record,
                    )

            if "create" in write:
                create_payloads = ensure_list(write["create"])
                if kind == "inverse_one" and len(create_payloads) > 1:
                    raise ValueError(f"Relation '{relation_name}' only accepts a single record")

                for payload in create_payloads:
                    if not isinstance(payload, Mapping):
                        raise ValueError(
                            f"Relation '{relation_name}' expects mapping payloads for create"
                        )
                    create_data = self._prepare_inverse_relation_create_data(
                        config,
                        record,
                        cast(Mapping[str, Any], payload),
                    )
                    await delegate.create(create_data)

            if "createMany" in write:
                if kind != "inverse_many":
                    raise PrismaClientValidationError(
                        f"Nested createMany is only supported by one-to-many relations; "
                        f"relation '{relation_name}' is {kind}."
                    )
                create_many_input = write["createMany"]
                if not isinstance(create_many_input, Mapping):
                    raise PrismaClientValidationError(
                        f"Relation '{relation_name}' createMany expects a mapping."
                    )
                raw_create_many_data = create_many_input.get("data")
                create_many_payloads = ensure_list(raw_create_many_data)
                prepared_create_many: List[Dict[str, Any]] = []
                for payload in create_many_payloads:
                    if not isinstance(payload, Mapping):
                        raise PrismaClientValidationError(
                            f"Relation '{relation_name}' createMany data expects mappings."
                        )
                    prepared_create_many.append(
                        self._prepare_inverse_relation_create_data(
                            config,
                            record,
                            cast(Mapping[str, Any], payload),
                        )
                    )
                if prepared_create_many:
                    await delegate.create_many(
                        prepared_create_many,
                        skip_duplicates=bool(
                            create_many_input.get(
                                "skipDuplicates",
                                create_many_input.get("skip_duplicates", False),
                            )
                        ),
                    )

            if "connect" in write:
                connect_records = await self._resolve_relation_records(
                    delegate,
                    write["connect"],
                    relation_name,
                )
                await self._attach_inverse_records(
                    delegate,
                    relation_name,
                    config,
                    connect_records,
                    record,
                )

            if "connectOrCreate" in write:
                connect_or_create_records = await self._connect_or_create_relation_records(
                    delegate,
                    write["connectOrCreate"],
                    relation_name,
                    lambda payload: self._prepare_inverse_relation_create_data(
                        relation_config,
                        record,
                        payload,
                    ),
                )
                await self._attach_inverse_records(
                    delegate,
                    relation_name,
                    config,
                    connect_or_create_records,
                    record,
                )

            if "update" in write:
                update_entries = self._normalize_nested_entries(write["update"], relation_name)
                if kind == "inverse_one" and len(update_entries) > 1:
                    raise ValueError(f"Relation '{relation_name}' only accepts a single update payload")

                for update_entry in update_entries:
                    if kind == "inverse_one":
                        target_records = await self._find_relation_records_for_write(
                            delegate,
                            relation_name,
                            config,
                            record,
                        )
                        self._ensure_singular_relation_write(relation_name, target_records)
                        if not target_records:
                            raise RecordNotFoundError(
                                f"Related record for '{relation_name}' was not found for nested update"
                            )
                        raw_data = update_entry.get("data")
                        if isinstance(raw_data, Mapping):
                            update_data = dict(raw_data)
                        else:
                            update_data = dict(update_entry)
                    else:
                        where_clause = update_entry.get("where")
                        data_clause = update_entry.get("data")
                        if not isinstance(where_clause, Mapping) or not isinstance(data_clause, Mapping):
                            raise ValueError(
                                f"Relation '{relation_name}' update expects 'where' and 'data' mappings"
                            )
                        target_records = await self._find_relation_records_for_write(
                            delegate,
                            relation_name,
                            config,
                            record,
                            cast(Mapping[str, Any], where_clause),
                        )
                        update_data = dict(data_clause)

                    await self._update_records_bulk(
                        delegate,
                        target_records,
                        cast(Mapping[str, Any], update_data),
                    )

            if kind == "inverse_many" and "updateMany" in write:
                update_many_entries = self._normalize_nested_entries(write["updateMany"], relation_name)
                for update_entry in update_many_entries:
                    data_clause = update_entry.get("data")
                    where_clause = update_entry.get("where")
                    if not isinstance(data_clause, Mapping):
                        raise ValueError(
                            f"Relation '{relation_name}' updateMany expects a 'data' mapping"
                        )

                    target_records = await self._find_relation_records_for_write(
                        delegate,
                        relation_name,
                        config,
                        record,
                        cast(Optional[Mapping[str, Any]], where_clause)
                        if isinstance(where_clause, Mapping)
                        else None,
                    )
                    for target_record in target_records:
                        await delegate.update(
                            delegate._build_primary_where(target_record),
                            cast(Dict[str, Any], dict(data_clause)),
                        )

            if "upsert" in write:
                upsert_entries = self._normalize_nested_entries(write["upsert"], relation_name)
                if kind == "inverse_one" and len(upsert_entries) > 1:
                    raise ValueError(f"Relation '{relation_name}' only accepts a single upsert payload")

                for upsert_entry in upsert_entries:
                    if kind == "inverse_one":
                        target_records = await self._find_relation_records_for_write(
                            delegate,
                            relation_name,
                            config,
                            record,
                        )
                        update_clause = upsert_entry.get("update")
                        create_clause = upsert_entry.get("create")
                    else:
                        where_clause = upsert_entry.get("where")
                        update_clause = upsert_entry.get("update")
                        create_clause = upsert_entry.get("create")
                        if not isinstance(where_clause, Mapping):
                            raise ValueError(
                                f"Relation '{relation_name}' upsert expects a 'where' mapping"
                            )
                        target_records = await self._find_relation_records_for_write(
                            delegate,
                            relation_name,
                            config,
                            record,
                            cast(Mapping[str, Any], where_clause),
                        )

                    if target_records:
                        if not isinstance(update_clause, Mapping):
                            raise ValueError(
                                f"Relation '{relation_name}' upsert expects an 'update' mapping"
                            )
                        await delegate.update(
                            delegate._build_primary_where(target_records[0]),
                            cast(Dict[str, Any], dict(update_clause)),
                        )
                    else:
                        if not isinstance(create_clause, Mapping):
                            raise ValueError(
                                f"Relation '{relation_name}' upsert expects a 'create' mapping"
                            )
                        create_data = self._prepare_inverse_relation_create_data(
                            config,
                            record,
                            cast(Mapping[str, Any], create_clause),
                        )
                        await delegate.create(create_data)

            if write.get("delete") is True:
                delete_records = await self._find_relation_records_for_write(
                    delegate,
                    relation_name,
                    config,
                    record,
                )
                if kind == "inverse_one":
                    self._ensure_singular_relation_write(relation_name, delete_records)
                await self._delete_records_bulk(delegate, delete_records)
            elif "delete" in write:
                delete_entries = self._normalize_nested_entries(write["delete"], relation_name)
                for delete_entry in delete_entries:
                    delete_records = await self._find_relation_records_for_write(
                        delegate,
                        relation_name,
                        config,
                        record,
                        cast(Mapping[str, Any], delete_entry),
                    )
                    if kind == "inverse_one":
                        self._ensure_singular_relation_write(relation_name, delete_records)
                    await self._delete_records_bulk(delegate, delete_records)

            if kind == "inverse_many" and "deleteMany" in write:
                delete_many_entries = self._normalize_nested_entries(write["deleteMany"], relation_name)
                for delete_entry in delete_many_entries:
                    delete_records = await self._find_relation_records_for_write(
                        delegate,
                        relation_name,
                        config,
                        record,
                        cast(Optional[Mapping[str, Any]], delete_entry),
                    )
                    await self._delete_records_bulk(delegate, delete_records)

            if write.get("disconnect") is True:
                await self._clear_inverse_relations(delegate, relation_name, config, record)
            elif "disconnect" in write:
                disconnect_records = await self._resolve_relation_records(
                    delegate,
                    write["disconnect"],
                    relation_name,
                )
                await self._detach_inverse_records(
                    delegate,
                    relation_name,
                    config,
                    disconnect_records,
                )

    async def update(
        self,
        where: UserWhereUniqueInput,
        data: UserUpdateInput,
        select: Optional[UserSelect] = None,
        omit: Optional[UserOmit] = None,
        include: Optional[UserInclude] = None,
    ) -> User:
        """Update a record"""
        validate_projection_options(select, omit, include)
        conn = await self._get_conn()

        normalized_where = self._normalize_unique_where(where)
        data_dict = dict(data)
        relation_writes = self._extract_relation_writes(data_dict)
        if relation_writes and not self._is_in_transaction():
            async with self._transaction_scope():
                return await self.update(where, data, select=select, omit=omit, include=include)
        data_dict["updatedAt"] = get_datetime_value(SQLBuilder.PROVIDER)

        has_scalar_list_operations = any(
            isinstance(data_dict.get(f), Mapping) for f in self.SCALAR_LIST_FIELDS
        )
        if (
            SQLBuilder.PROVIDER in ("postgresql", "sqlite")
            and not relation_writes
            and not has_scalar_list_operations
        ):
            # Single-statement fast path: UPDATE ... RETURNING collapses the
            # exists-check + UPDATE + re-read cycle (3 round trips) into one
            # statement. An empty RETURNING set is the P2025 case.
            fast_data = dict(data_dict)
            for key in list(fast_data.keys()):
                if key not in self.FIELDS_SET:
                    del fast_data[key]

            atomic_ops = self._extract_atomic_operations(fast_data)

            for k, v in list(fast_data.items()):
                if k in self.SCALAR_LIST_FIELDS_SET and not isinstance(v, Mapping):
                    fast_data[k] = serialize_scalar_list_field_value(
                        v,
                        self.SCALAR_LIST_FIELD_TYPES.get(k, "Any"),
                        self.SCALAR_LIST_ENUM_FIELDS.get(k),
                    )
                elif k in self.JSON_FIELDS_SET:
                    fast_data[k] = serialize_json_field_value(v)
                elif k in self.DECIMAL_FIELDS_SET:
                    fast_data[k] = normalize_decimal_field_value(v, SQLBuilder.PROVIDER)
                elif isinstance(v, bool):
                    if SQLBuilder.PROVIDER == "sqlite":
                        fast_data[k] = 1 if v else 0
                    else:
                        fast_data[k] = v
                elif k in self.DATETIME_FIELDS_SET:
                    fast_data[k] = normalize_datetime_field_value(v, SQLBuilder.PROVIDER)
                elif isinstance(v, PyEnum):
                    fast_data[k] = v.value

            set_parts, values, next_param_index = self._build_update_set_parts(fast_data, atomic_ops)
            where_sql, where_params, _ = SQLBuilder.build_where(
                normalized_where,
                "",
                next_param_index,
                self.FIELD_TO_COLUMN,
                self.SCALAR_LIST_FIELDS,
            )
            if set_parts and where_sql:
                returning_sql, selected_fields = self.FULL_ROW_SELECT
                sql = (
                    f'UPDATE {SQLBuilder.quote_identifier(self.TABLE)} '
                    f'SET {", ".join(set_parts)} WHERE {where_sql} '
                    f'RETURNING {returning_sql}'
                )
                rows = await fetch_dict_rows(conn, sql, values + where_params, selected_fields)
                await self._commit_if_needed(conn)
                if not rows:
                    raise RecordNotFoundError(
                        "An operation failed because it depends on one or more records "
                        "that were required but not found.",
                        {"modelName": "User", "cause": "Record to update not found."},
                    )
                stored_record = self._row_to_model(rows[0], selected_fields)
                if not (select or omit or include):
                    return stored_record
                relation_load_options = self._build_relation_load_options(select, include)
                count_requests = self._extract_count_requests(select, include)
                if not relation_load_options and not count_requests:
                    return self._apply_query_options(stored_record, select, omit, include)
                record_where = cast(UserWhereUniqueInput, self._build_primary_where(stored_record))
                projected_record = await self.find_unique(record_where, select=select, omit=omit, include=include)
                if projected_record is None:
                    raise RecordNotFoundError("Failed to load User after update")
                return projected_record

        existing = await self.find_unique(where)
        if not existing:
            raise RecordNotFoundError(
                "An operation failed because it depends on one or more records "
                "that were required but not found.",
                {"modelName": "User", "cause": "Record to update not found."},
            )

        await self._apply_pre_write_relations(data_dict, relation_writes, existing)
        for key in list(data_dict.keys()):
            if key not in self.FIELDS_SET:
                del data_dict[key]

        atomic_ops = self._extract_atomic_operations(data_dict)

        for field in self.SCALAR_LIST_FIELDS:
            if field in data_dict and isinstance(data_dict[field], Mapping):
                current = getattr(existing, field)
                data_dict[field] = apply_scalar_list_update(current, data_dict[field])

        for k, v in list(data_dict.items()):
            if k in self.SCALAR_LIST_FIELDS_SET:
                data_dict[k] = serialize_scalar_list_field_value(
                    v,
                    self.SCALAR_LIST_FIELD_TYPES.get(k, "Any"),
                    self.SCALAR_LIST_ENUM_FIELDS.get(k),
                )
            elif k in self.JSON_FIELDS_SET:
                data_dict[k] = serialize_json_field_value(v)
            elif k in self.DECIMAL_FIELDS_SET:
                data_dict[k] = normalize_decimal_field_value(v, SQLBuilder.PROVIDER)
            elif isinstance(v, bool):
                if SQLBuilder.PROVIDER == "sqlite":
                    data_dict[k] = 1 if v else 0
                else:
                    data_dict[k] = v
            elif k in self.DATETIME_FIELDS_SET:
                data_dict[k] = normalize_datetime_field_value(v, SQLBuilder.PROVIDER)
            elif isinstance(v, PyEnum):
                data_dict[k] = v.value

        record_where = cast(UserWhereUniqueInput, self._build_primary_where(existing))
        set_parts, values, next_param_index = self._build_update_set_parts(data_dict, atomic_ops)
        if not set_parts:
            stored_record = await self.find_unique(record_where)
            if stored_record is None:
                # The row vanished between the existence check and the re-read
                # (concurrent delete); Prisma raises P2025 here, not None.
                raise RecordNotFoundError(
                    "An operation failed because it depends on one or more records "
                    "that were required but not found.",
                    {"modelName": "User", "cause": "Record to update not found."},
                )
            await self._apply_post_write_relations(stored_record, relation_writes)
            if not (select or omit or include):
                return stored_record
            projected_record = await self.find_unique(record_where, select=select, omit=omit, include=include)
            if projected_record is None:
                raise RecordNotFoundError("Failed to load User after update")
            return projected_record

        set_clause = ", ".join(set_parts)
        where_sql, where_params, _ = SQLBuilder.build_where(
            normalized_where,
            "",
            next_param_index,
            self.FIELD_TO_COLUMN,
            self.SCALAR_LIST_FIELDS,
        )
        sql = f'UPDATE {SQLBuilder.quote_identifier(self.TABLE)} SET {set_clause} WHERE {where_sql}'

        await execute_write_query(conn, sql, values + where_params, self._commit_if_needed)

        stored_record = await self.find_unique(record_where)
        if stored_record is None:
            # The row vanished between the UPDATE and the re-read (concurrent
            # delete); Prisma raises P2025 here, not None.
            raise RecordNotFoundError(
                "An operation failed because it depends on one or more records "
                "that were required but not found.",
                {"modelName": "User", "cause": "Record to update not found."},
            )

        await self._apply_post_write_relations(stored_record, relation_writes)
        if not (select or omit or include):
            return stored_record
        projected_record = await self.find_unique(record_where, select=select, omit=omit, include=include)
        if projected_record is None:
            raise RecordNotFoundError("Failed to load User after update")
        return projected_record

    async def update_many(
        self,
        where: Optional[UserWhereInput],
        data: UserUpdateInput,
        limit: Optional[int] = None,
    ) -> Dict[str, int]:
        """Update multiple records"""
        data_dict = dict(data)
        data_dict["updatedAt"] = get_datetime_value(SQLBuilder.PROVIDER)

        for key in list(data_dict.keys()):
            if key not in self.FIELDS_SET:
                del data_dict[key]

        has_scalar_list_operations = any(
            isinstance(data_dict.get(f), Mapping) for f in self.SCALAR_LIST_FIELDS
        )
        where_requires_python_evaluation = self._where_requires_python_evaluation(where)

        if has_scalar_list_operations or where_requires_python_evaluation or limit is not None:
            # Per-record path: scalar-list mutations need read-modify-write, a
            # Python-evaluated filter needs hydration, and 'limit' needs a bounded
            # target list. The payload is passed through unserialized (update()
            # serializes it once), and atomic numeric dicts stay inside so update()
            # applies them atomically in SQL per row.
            records = await self.find_many(where=where, take=limit)
            scalar_data = cast(UserUpdateInput, data_dict)
            for rec in records:
                await self.update(
                    cast(UserWhereUniqueInput, self._build_primary_where(rec)),
                    scalar_data,
                )
            return {"count": len(records)}

        atomic_ops = self._extract_atomic_operations(data_dict)

        for k, v in list(data_dict.items()):
            if k in self.SCALAR_LIST_FIELDS_SET and not isinstance(v, Mapping):
                data_dict[k] = serialize_scalar_list_field_value(
                    v,
                    self.SCALAR_LIST_FIELD_TYPES.get(k, "Any"),
                    self.SCALAR_LIST_ENUM_FIELDS.get(k),
                )
            elif k in self.JSON_FIELDS_SET:
                data_dict[k] = serialize_json_field_value(v)
            elif k in self.DECIMAL_FIELDS_SET:
                data_dict[k] = normalize_decimal_field_value(v, SQLBuilder.PROVIDER)
            elif isinstance(v, bool):
                if SQLBuilder.PROVIDER == "sqlite":
                    data_dict[k] = 1 if v else 0
                else:
                    data_dict[k] = v
            elif k in self.DATETIME_FIELDS_SET:
                data_dict[k] = normalize_datetime_field_value(v, SQLBuilder.PROVIDER)
            elif isinstance(v, PyEnum):
                data_dict[k] = v.value

        conn = await self._get_conn()
        set_parts, values, next_param_index = self._build_update_set_parts(data_dict, atomic_ops)
        if not set_parts:
            # Nothing to write; report how many rows the filter matches.
            return {"count": await self.count(where=where)}

        set_clause = ", ".join(set_parts)
        where_sql = ""
        where_params: List[Any] = []
        if where:
            where_sql, where_params, _ = self._build_sql_where(dict(where), "", next_param_index)
        sql = f'UPDATE {SQLBuilder.quote_identifier(self.TABLE)} SET {set_clause}'
        if where_sql:
            sql += f" WHERE {where_sql}"

        count = await execute_write_query(
            conn,
            sql,
            values + where_params,
            self._commit_if_needed,
        )

        return {"count": count}

    async def update_many_and_return(
        self,
        data: UserUpdateInput,
        where: Optional[UserWhereInput] = None,
        limit: Optional[int] = None,
        select: Optional[UserSelect] = None,
        omit: Optional[UserOmit] = None,
    ) -> List[User]:
        """Update multiple records and return the stored rows"""
        data_dict = dict(data)
        for field in self.UPDATED_AT_FIELDS:
            data_dict[field] = get_datetime_value(SQLBuilder.PROVIDER)

        for key in list(data_dict.keys()):
            if key not in self.FIELDS_SET:
                del data_dict[key]

        has_scalar_list_operations = any(
            isinstance(data_dict.get(f), Mapping) for f in self.SCALAR_LIST_FIELDS
        )
        where_requires_python_evaluation = self._where_requires_python_evaluation(where)
        # Scalar-list mutations need per-record read-modify-write and Python-evaluated
        # filters need hydration; everything else - including atomic numeric ops, which
        # compile to "SET col = col + ?" - can run as one UPDATE statement.
        can_use_single_statement = (
            not has_scalar_list_operations and not where_requires_python_evaluation
        )

        atomic_ops: Dict[str, Tuple[str, Any]] = {}
        if can_use_single_statement:
            atomic_ops = self._extract_atomic_operations(data_dict)

            for k, v in list(data_dict.items()):
                if k in self.SCALAR_LIST_FIELDS_SET and not isinstance(v, Mapping):
                    data_dict[k] = serialize_scalar_list_field_value(
                        v,
                        self.SCALAR_LIST_FIELD_TYPES.get(k, "Any"),
                        self.SCALAR_LIST_ENUM_FIELDS.get(k),
                    )
                elif k in self.JSON_FIELDS_SET:
                    data_dict[k] = serialize_json_field_value(v)
                elif k in self.DECIMAL_FIELDS_SET:
                    data_dict[k] = normalize_decimal_field_value(v, SQLBuilder.PROVIDER)
                elif isinstance(v, bool):
                    if SQLBuilder.PROVIDER == "sqlite":
                        data_dict[k] = 1 if v else 0
                    else:
                        data_dict[k] = v
                elif k in self.DATETIME_FIELDS_SET:
                    data_dict[k] = normalize_datetime_field_value(v, SQLBuilder.PROVIDER)
                elif isinstance(v, PyEnum):
                    data_dict[k] = v.value

        if can_use_single_statement and SQLBuilder.PROVIDER != "mysql" and limit is None:
            set_parts, values, next_param_index = self._build_update_set_parts(data_dict, atomic_ops)
            if set_parts:
                conn = await self._get_conn()
                where_sql = ""
                where_params: List[Any] = []
                if where:
                    where_sql, where_params, _ = self._build_sql_where(dict(where), "", next_param_index)

                returning_sql, selected_fields = SQLBuilder.build_select(
                    self.TABLE,
                    self.FIELDS,
                    cast(Optional[SelectDict], select),
                    cast(Optional[SelectDict], omit),
                    field_map=self.FIELD_TO_COLUMN,
                )
                sql = (
                    f'UPDATE {SQLBuilder.quote_identifier(self.TABLE)} '
                    f'SET {", ".join(set_parts)}'
                )
                if where_sql:
                    sql += f" WHERE {where_sql}"
                sql += f" RETURNING {returning_sql}"

                rows = await fetch_dict_rows(
                    conn,
                    sql,
                    values + where_params,
                    selected_fields,
                )
                await self._commit_if_needed(conn)
                results = [self._row_to_model(row, selected_fields) for row in rows]
                for record in results:
                    self._apply_query_options(record, select, omit, None)
                return results

        # MySQL has no "UPDATE ... RETURNING", so it cannot use the single-statement path
        # above. Rather than fall to the per-row loop below (1 + N round-trips), capture the
        # matching primary keys once, apply the change with a single bulk UPDATE per chunk,
        # then re-select the stored rows - a fixed handful of round-trips regardless of N.
        # Scalar-list mutations and Python-evaluated filters still take the exact per-row
        # loop, since those need per-record read-modify-write semantics.
        if can_use_single_statement and SQLBuilder.PROVIDER == "mysql":
            targets = await self.find_many(where=where, take=limit)
            if not targets:
                return []

            # Plain PK-equality WhereInput per row (column = value), not the compound
            # WhereUniqueInput selector shape, so OR-of-keys builds real SQL conditions
            # for both single and composite primary keys.
            def _pk_eq_where(rec: Any) -> Dict[str, Any]:
                return {field: getattr(rec, field) for field in self.PK_FIELDS}

            set_parts, set_values, next_param_index = self._build_update_set_parts(data_dict, atomic_ops)
            if set_parts:
                conn = await self._get_conn()
                set_clause = ", ".join(set_parts)

                # Chunk so neither the UPDATE nor the re-select binds more than _MAX_SQL_VARS
                # placeholders; each chunk is a disjoint set of primary keys.
                for _batch in _chunk(targets):
                    batch_pk_where = {"OR": [_pk_eq_where(rec) for rec in _batch]}
                    where_sql, where_params, _ = self._build_sql_where(
                        dict(batch_pk_where), "", next_param_index
                    )
                    bulk_sql = (
                        f'UPDATE {SQLBuilder.quote_identifier(self.TABLE)} '
                        f'SET {set_clause} WHERE {where_sql}'
                    )
                    await execute_write_query(
                        conn, bulk_sql, set_values + where_params, self._commit_if_needed
                    )

            refreshed: List[User] = []
            for _batch in _chunk(targets):
                batch_pk_where = cast(
                    UserWhereInput, {"OR": [_pk_eq_where(rec) for rec in _batch]}
                )
                refreshed.extend(
                    await self.find_many(where=batch_pk_where, select=select, omit=omit)
                )

            # Return the stored rows in the original match order.
            by_pk = {
                self._identity_for_fields(rec, self.PK_FIELDS): rec for rec in refreshed
            }
            ordered: List[User] = []
            for rec in targets:
                match = by_pk.get(self._identity_for_fields(rec, self.PK_FIELDS))
                if match is not None:
                    ordered.append(match)
            return ordered

        records = await self.find_many(where=where, take=limit)
        updated_records: List[User] = []
        for record in records:
            updated = await self.update(
                cast(UserWhereUniqueInput, self._build_primary_where(record)),
                data,
                select=select,
                omit=omit,
            )
            if updated is not None:
                updated_records.append(updated)

        return updated_records

    async def delete(
        self,
        where: UserWhereUniqueInput,
        select: Optional[UserSelect] = None,
        omit: Optional[UserOmit] = None,
        include: Optional[UserInclude] = None,
    ) -> User:
        """Delete a record"""
        validate_projection_options(select, omit, include)
        conn = await self._get_conn()

        existing = await self.find_unique(where, select=select, omit=omit, include=include)
        if not existing:
            raise RecordNotFoundError(
                "An operation failed because it depends on one or more records "
                "that were required but not found.",
                {"modelName": "User", "cause": "Record to delete does not exist."},
            )

        normalized_where = self._normalize_unique_where(where)
        where_sql, params, _ = SQLBuilder.build_where(
            normalized_where,
            field_map=self.FIELD_TO_COLUMN,
            scalar_list_fields=self.SCALAR_LIST_FIELDS,
        )
        sql = f'DELETE FROM {SQLBuilder.quote_identifier(self.TABLE)} WHERE {where_sql}'

        await execute_write_query(conn, sql, params, self._commit_if_needed)
        return existing

    async def delete_many(
        self,
        where: Optional[UserWhereInput] = None,
    ) -> Dict[str, int]:
        """Delete multiple records"""
        where_requires_python_evaluation = self._where_requires_python_evaluation(where)
        if where_requires_python_evaluation:
            records = await self.find_many(where=where)
            for record in records:
                await self.delete(cast(UserWhereUniqueInput, self._build_primary_where(record)))
            return {"count": len(records)}

        conn = await self._get_conn()

        sql = f'DELETE FROM {SQLBuilder.quote_identifier(self.TABLE)}'
        params: List[Any] = []

        if where:
            where_sql, params, _ = self._build_sql_where(dict(where))
            if where_sql:
                sql += f" WHERE {where_sql}"

        count = await execute_write_query(conn, sql, params, self._commit_if_needed)
        return {"count": count}

    async def count(
        self,
        where: Optional[UserWhereInput] = None,
        cursor: Optional[UserWhereUniqueInput] = None,
        take: Optional[int] = None,
        skip: Optional[int] = None,
    ) -> int:
        """Count records"""
        where_requires_python_evaluation = self._where_requires_python_evaluation(where)
        if cursor or where_requires_python_evaluation or (take is not None and take < 0):
            records = await self.find_many(where=where, cursor=cursor, take=take, skip=skip)
            return len(records)

        conn = await self._get_conn()
        where_sql = ""
        params: List[Any] = []

        if where:
            where_sql, params, _ = self._build_sql_where(dict(where))
        return await execute_count_query(conn, self.TABLE, where_sql, params, take, skip)

    async def upsert(
        self,
        where: UserWhereUniqueInput,
        create: UserCreateInput,
        update: UserUpdateInput,
        select: Optional[UserSelect] = None,
        omit: Optional[UserOmit] = None,
        include: Optional[UserInclude] = None,
    ) -> User:
        """Update or create"""
        validate_projection_options(select, omit, include)
        create_dict = dict(create)
        update_dict = dict(update)
        normalized_where = self._normalize_unique_where(where)
        conflict_fields = self._unique_fields_for_normalized_where(normalized_where)

        has_relation_writes = any(
            key in self.RELATION_CONFIGS
            for key in list(create_dict.keys()) + list(update_dict.keys())
        )
        has_atomic_updates = any(
            field in update_dict and isinstance(update_dict[field], Mapping)
            for field in self.NUMERIC_FIELDS
        )
        has_scalar_list_operations = any(
            field in update_dict and isinstance(update_dict[field], Mapping)
            for field in self.SCALAR_LIST_FIELDS
        )

        can_use_native_upsert = bool(conflict_fields) and not (
            has_relation_writes or has_atomic_updates or has_scalar_list_operations
        )

        if can_use_native_upsert:
            create_dict = self._generate_defaults(create_dict)
            update_dict["updatedAt"] = get_datetime_value(SQLBuilder.PROVIDER)
            create_dict = self._prepare_create_data(create_dict)
            update_dict = self._prepare_create_data(update_dict)
            normalized_conflict_values = self._prepare_create_data(dict(normalized_where))

            assert conflict_fields is not None
            for field in conflict_fields:
                if field not in create_dict or create_dict.get(field) != normalized_conflict_values.get(field):
                    can_use_native_upsert = False
                    break

            insert_fields = [field for field in create_dict.keys() if field in self.FIELDS_SET]
            update_fields = [
                field
                for field in update_dict.keys()
                if field in self.FIELDS_SET and field not in self.PK_FIELDS_SET
            ]
            if not insert_fields:
                can_use_native_upsert = False

            if can_use_native_upsert:
                conn = await self._get_conn()
                insert_values = [create_dict[field] for field in insert_fields]
                update_values = [update_dict[field] for field in update_fields]
                await execute_native_upsert(
                    conn,
                    self.TABLE,
                    [self._db_column(field) for field in conflict_fields],
                    [self._db_column(field) for field in insert_fields],
                    insert_values,
                    [self._db_column(field) for field in update_fields],
                    update_values,
                    self._commit_if_needed,
                )

                result = await self.find_unique(where, select=select, omit=omit, include=include)
                if result is None:
                    raise RecordNotFoundError("Failed to load User after upsert")
                return result

        existing = await self.find_unique(where)
        if existing:
            result = await self.update(where, update, select=select, omit=omit, include=include)
            if result is None:
                raise RecordNotFoundError("Failed to update User")
            return result
        return await self.create(create, select=select, omit=omit, include=include)

    async def aggregate(
        self,
        where: Optional[UserWhereInput] = None,
        _count: Optional[Union[bool, Dict[str, bool]]] = None,
        _avg: Optional[Dict[str, bool]] = None,
        _sum: Optional[Dict[str, bool]] = None,
        _min: Optional[Dict[str, bool]] = None,
        _max: Optional[Dict[str, bool]] = None,
    ) -> Dict[str, Any]:
        """Aggregate operations"""
        where_requires_python_evaluation = self._where_requires_python_evaluation(where)
        if where_requires_python_evaluation:
            records = await self.find_many(where=where)
            return build_python_aggregate_result(
                records,
                self.FIELDS,
                _count,
                _avg,
                _sum,
                _min,
                _max,
            )

        conn = await self._get_conn()
        where_sql = ""
        params: List[Any] = []
        if where:
            where_sql, params, _ = self._build_sql_where(dict(where))
        return await execute_sql_aggregate(
            conn,
            self.TABLE,
            self.FIELDS,
            where_sql,
            params,
            _count,
            _avg,
            _sum,
            _min,
            _max,
            self.FIELD_TO_COLUMN,
        )

    async def group_by(
        self,
        by: List[str],
        where: Optional[UserWhereInput] = None,
        order_by: Optional[Union[List[Dict[str, Any]], Dict[str, Any]]] = None,
        having: Optional[Dict[str, Any]] = None,
        take: Optional[int] = None,
        skip: Optional[int] = None,
        _count: Optional[Union[bool, Dict[str, bool]]] = None,
        _avg: Optional[Dict[str, bool]] = None,
        _sum: Optional[Dict[str, bool]] = None,
        _min: Optional[Dict[str, bool]] = None,
        _max: Optional[Dict[str, bool]] = None,
    ) -> List[Dict[str, Any]]:
        """Group records by scalar fields and compute aggregates"""
        if not by:
            raise ValueError("group_by requires at least one field in 'by'")

        invalid_fields = [field for field in by if field not in self.FIELDS_SET]
        if invalid_fields:
            raise ValueError(f"Invalid group_by fields: {invalid_fields}")

        valid_fields = set(self.FIELDS)
        requested_aggregate_inputs = {
            "_avg": _avg,
            "_sum": _sum,
            "_min": _min,
            "_max": _max,
        }
        requested_aggregate_maps = {
            agg_name: dict(agg_fields) if agg_fields else None
            for agg_name, agg_fields in requested_aggregate_inputs.items()
        }
        requested_count_map = dict(_count) if isinstance(_count, Mapping) else None

        # Aggregate rows may be needed for output, having filters, or aggregate order_by clauses.
        having_aggregate_inputs = collect_group_by_having_aggregates(having)
        order_by_aggregate_inputs = collect_group_by_order_by_aggregates(order_by)

        computed_aggregate_inputs: Dict[str, Dict[str, bool]] = {}
        for agg_name, requested_fields in requested_aggregate_maps.items():
            merged_fields = {
                **build_truthy_field_map(requested_fields, valid_fields),
                **build_truthy_field_map(having_aggregate_inputs.get(agg_name), valid_fields),
                **build_truthy_field_map(order_by_aggregate_inputs.get(agg_name), valid_fields),
            }
            if merged_fields:
                computed_aggregate_inputs[agg_name] = merged_fields

        include_count_all = _count is True or bool(requested_count_map and requested_count_map.get("_all"))
        requested_count_fields = build_truthy_field_map(
            requested_count_map,
            valid_fields,
            {"_all"},
        )
        computed_count_fields = {
            **requested_count_fields,
            **build_truthy_field_map(having_aggregate_inputs.get("_count"), valid_fields),
            **build_truthy_field_map(order_by_aggregate_inputs.get("_count"), valid_fields),
        }
        order_by_clauses = [
            clause for clause in ensure_list(order_by)
            if isinstance(clause, Mapping)
        ]
        where_requires_python_evaluation = self._where_requires_python_evaluation(where)
        can_use_sql_group_by = (
            not having
            and not where_requires_python_evaluation
            and len(set(by)) == len(by)
            and not any(field in self.JSON_FIELDS_SET or field in self.SCALAR_LIST_FIELDS_SET for field in by)
            and (take is None or take >= 0)
            and (skip is None or skip >= 0)
            and not (skip and take is None)
        )

        sql_order_parts: List[str] = []
        if can_use_sql_group_by:
            for order_clause in order_by_clauses:
                for order_field, direction in dict(order_clause).items():
                    if order_field not in by or isinstance(direction, Mapping):
                        can_use_sql_group_by = False
                        break

                    direction_sql = "DESC" if str(direction).lower() == "desc" else "ASC"
                    sql_order_parts.append(
                        f"{SQLBuilder.quote_identifier(self._db_column(order_field))} {direction_sql}"
                    )
                if not can_use_sql_group_by:
                    break

        if can_use_sql_group_by:
            params: List[Any] = []
            where_sql = ""
            if where:
                where_sql, params, _ = self._build_sql_where(dict(where))

            conn = await self._get_conn()
            return await execute_sql_group_by(
                conn,
                self.TABLE,
                self.FIELDS,
                by,
                where_sql,
                params,
                sql_order_parts,
                take,
                skip,
                include_count_all,
                requested_count_map,
                computed_count_fields,
                computed_aggregate_inputs,
                requested_aggregate_maps,
                _count,
                self.FIELD_TO_COLUMN,
            )

        # When the filter itself forces the Python path, find_many already logs the
        # full-table scan. Only warn here for the group_by-specific reasons (having,
        # JSON/scalar-list grouping key, duplicate keys, or unsupported take/skip), so
        # that degradation is visible without double-logging the where-filter case.
        if not where_requires_python_evaluation:
            _warn_full_scan(
                "User",
                "group_by not SQL-expressible (having / JSON or scalar-list grouping key / "
                "duplicate keys / unsupported take/skip)",
            )
        records = await self.find_many(where=where)
        return build_python_group_by_rows(
            records,
            self.FIELDS,
            by,
            having,
            valid_fields,
            order_by_clauses,
            take,
            skip,
            include_count_all,
            requested_count_map,
            computed_count_fields,
            computed_aggregate_inputs,
            requested_aggregate_maps,
            _count,
        )



class UserRoleDelegate(BaseDelegate):
    """Async Direct SQL delegate for UserRole"""

    TABLE = "UserRole"
    PK_FIELDS = USERROLE_PK_FIELDS
    PK_SELECTOR = USERROLE_PK_SELECTOR
    UNIQUE_SELECTORS = USERROLE_UNIQUE_SELECTORS
    FIELDS = USERROLE_FIELDS
    FIELD_TO_COLUMN = USERROLE_FIELD_TO_COLUMN
    COLUMN_TO_FIELD = USERROLE_COLUMN_TO_FIELD
    NUMERIC_FIELDS = USERROLE_NUMERIC_FIELDS
    INT_FIELDS = ["id"]
    INT_FIELDS_SET: FrozenSet[str] = frozenset(INT_FIELDS)
    DECIMAL_FIELDS = USERROLE_DECIMAL_FIELDS
    DECIMAL_FIELDS_SET: FrozenSet[str] = frozenset(DECIMAL_FIELDS)
    DATETIME_FIELDS = USERROLE_DATETIME_FIELDS
    UPDATED_AT_FIELDS = USERROLE_UPDATED_AT_FIELDS
    JSON_FIELDS = USERROLE_JSON_FIELDS
    SCALAR_LIST_FIELDS = USERROLE_SCALAR_LIST_FIELDS
    SCALAR_LIST_FIELD_TYPES = USERROLE_SCALAR_LIST_FIELD_TYPES
    ENUM_FIELDS = USERROLE_ENUM_FIELDS
    SCALAR_LIST_ENUM_FIELDS = USERROLE_SCALAR_LIST_ENUM_FIELDS
    RELATION_CONFIGS: Dict[str, Dict[str, Any]] = {
        "user": {"model": "User", "kind": "inverse_many", "local_fields": ["id"], "remote_fields": ["roleId"], "can_disconnect": True}
    }

    def _row_to_model(self, row: Any, columns: List[str]) -> UserRole:
        """Convert row to model instance"""
        if isinstance(row, dict):
            if self.HAS_COLUMN_ALIASES:
                data = {
                    self._logical_field(str(key)): value
                    for key, value in row.items()
                }
            else:
                # No @map'd columns: DB keys already equal logical field names, so a
                # plain copy avoids a per-key method call and str() on the hot path.
                data = dict(row)
        else:
            data = dict(zip(columns, row))
        # Convert datetime strings back to datetime objects





        # Convert enum string values back to enum instances
        for enum_field, enum_class in self.ENUM_FIELDS.items():
            if enum_field in data and data[enum_field] is not None:
                try:
                    data[enum_field] = enum_class(data[enum_field])
                except (ValueError, KeyError):
                    pass  # Keep original value if conversion fails
        return UserRole(**{k: v for k, v in data.items() if k in self.FIELDS_SET})

    def _relation_filter_requires_python_evaluation(
        self,
        relation_name: str,
        condition: Any,
    ) -> bool:
        config = self.RELATION_CONFIGS.get(relation_name)
        if config is None or not isinstance(condition, Mapping):
            return True

        related_delegate = self._get_delegate(cast(str, config["model"]))
        if related_delegate is None:
            return True

        # SQL generation currently uses table names as references. Self-relations
        # need aliases to avoid ambiguous identifiers, so keep those on the safe
        # Python path until alias-aware SQL generation lands.
        if related_delegate.TABLE == self.TABLE:
            return True

        kind = cast(str, config["kind"])
        condition_dict = dict(condition)

        if kind in ("m2m", "inverse_many"):
            for operator, nested_where in condition_dict.items():
                if operator not in ("some", "none", "every"):
                    return True
                if not isinstance(nested_where, Mapping):
                    return True
                if related_delegate._where_requires_python_evaluation(
                    cast(Mapping[str, Any], nested_where)
                ):
                    return True
            return False

        relation_operators = [
            operator for operator in condition_dict.keys() if operator in ("is", "isNot")
        ]
        if relation_operators:
            for operator, nested_where in condition_dict.items():
                if operator not in ("is", "isNot"):
                    return True
                if nested_where is None:
                    continue
                if not isinstance(nested_where, Mapping):
                    return True
                if related_delegate._where_requires_python_evaluation(
                    cast(Mapping[str, Any], nested_where)
                ):
                    return True
            return False

        return related_delegate._where_requires_python_evaluation(condition_dict)

    def _build_relation_exists_sql(
        self,
        relation_name: str,
        config: Mapping[str, Any],
        nested_where: Optional[Mapping[str, Any]],
        param_offset: int,
        negate_nested: bool = False,
    ) -> Tuple[str, List[Any], int]:
        related_delegate = self._get_delegate(cast(str, config["model"]))
        if related_delegate is None:
            raise ValueError(f"Unknown relation delegate for '{relation_name}'")

        kind = cast(str, config["kind"])
        params: List[Any] = []
        idx = param_offset

        if kind == "m2m":
            join_table = cast(str, config["join_table"])
            local_column = cast(str, config["local_column"])
            remote_column = cast(str, config["remote_column"])
            local_pk_field = cast(str, config["local_pk_field"])
            remote_pk_field = cast(str, config["remote_pk_field"])
            conditions = [
                f"{SQLBuilder.column_ref(local_column, join_table)} = {SQLBuilder.column_ref(self._db_column(local_pk_field), self.TABLE)}"
            ]

            join_sql = (
                f"{SQLBuilder.quote_identifier(join_table)} "
                f"INNER JOIN {SQLBuilder.quote_identifier(related_delegate.TABLE)} "
                f"ON {SQLBuilder.column_ref(related_delegate._db_column(remote_pk_field), related_delegate.TABLE)} = "
                f"{SQLBuilder.column_ref(remote_column, join_table)}"
            )
        else:
            local_fields = cast(List[str], config["local_fields"])
            remote_fields = cast(List[str], config["remote_fields"])
            conditions = [
                f"{SQLBuilder.column_ref(related_delegate._db_column(remote_field), related_delegate.TABLE)} = {SQLBuilder.column_ref(self._db_column(local_field), self.TABLE)}"
                for local_field, remote_field in zip(local_fields, remote_fields)
            ]
            join_sql = SQLBuilder.quote_identifier(related_delegate.TABLE)

        if nested_where:
            nested_sql, nested_params, idx = related_delegate._build_sql_where(
                cast(Mapping[str, Any], nested_where),
                related_delegate.TABLE,
                idx,
            )
            if nested_sql:
                conditions.append(f"NOT ({nested_sql})" if negate_nested else f"({nested_sql})")
                params.extend(nested_params)

        where_sql = " AND ".join(conditions) if conditions else "1 = 1"
        return f"EXISTS (SELECT 1 FROM {join_sql} WHERE {where_sql})", params, idx

    def _build_relation_filter_sql(
        self,
        relation_name: str,
        condition: Any,
        param_offset: int,
    ) -> Tuple[str, List[Any], int]:
        config = self.RELATION_CONFIGS.get(relation_name)
        if config is None or not isinstance(condition, Mapping):
            raise ValueError(f"Unsupported relation filter for '{relation_name}'")

        kind = cast(str, config["kind"])
        condition_dict = dict(condition)
        clauses: List[str] = []
        params: List[Any] = []
        idx = param_offset

        if kind in ("m2m", "inverse_many"):
            for operator, nested_where in condition_dict.items():
                nested_mapping = cast(Mapping[str, Any], nested_where)
                if operator == "every" and not nested_mapping:
                    continue
                exists_sql, exists_params, idx = self._build_relation_exists_sql(
                    relation_name,
                    config,
                    nested_mapping,
                    idx,
                    negate_nested=operator == "every",
                )
                if operator == "some":
                    clauses.append(exists_sql)
                elif operator in ("none", "every"):
                    clauses.append(f"NOT ({exists_sql})")
                else:
                    raise ValueError(
                        f"Unsupported list relation filter operation '{operator}' for relation '{relation_name}'"
                    )
                params.extend(exists_params)
            return " AND ".join(clauses), params, idx

        relation_operators = [
            operator for operator in condition_dict.keys() if operator in ("is", "isNot")
        ]
        if relation_operators:
            for operator, nested_where in condition_dict.items():
                if operator not in ("is", "isNot"):
                    raise ValueError(
                        f"Unsupported to-one relation filter operation '{operator}' for relation '{relation_name}'"
                    )
                is_null_check = nested_where is None
                nested_mapping = None if is_null_check else cast(Mapping[str, Any], nested_where)
                exists_sql, exists_params, idx = self._build_relation_exists_sql(
                    relation_name,
                    config,
                    nested_mapping,
                    idx,
                )
                # A null target flips the meaning: {is: null} matches rows with NO related
                # record (NOT EXISTS), {isNot: null} matches rows that HAVE one (EXISTS).
                # With a nested filter it is the usual {is} -> EXISTS, {isNot} -> NOT EXISTS.
                if is_null_check:
                    clauses.append(f"NOT ({exists_sql})" if operator == "is" else exists_sql)
                else:
                    clauses.append(exists_sql if operator == "is" else f"NOT ({exists_sql})")
                params.extend(exists_params)
            return " AND ".join(clauses), params, idx

        exists_sql, exists_params, idx = self._build_relation_exists_sql(
            relation_name,
            config,
            condition_dict,
            idx,
        )
        return exists_sql, exists_params, idx

    def _build_sql_where(
        self,
        where: Optional[Mapping[str, Any]],
        table: str = "",
        param_offset: int = 0,
    ) -> Tuple[str, List[Any], int]:
        if not where:
            return "", [], param_offset

        conditions: List[str] = []
        params: List[Any] = []
        idx = param_offset

        for key, value in dict(where).items():
            if key == "AND":
                sub_conditions: List[str] = []
                for clause in ensure_list(value):
                    if not isinstance(clause, Mapping):
                        continue
                    sql, nested_params, idx = self._build_sql_where(
                        cast(Mapping[str, Any], clause),
                        table,
                        idx,
                    )
                    if sql:
                        sub_conditions.append(f"({sql})")
                        params.extend(nested_params)
                if sub_conditions:
                    conditions.append(f"({' AND '.join(sub_conditions)})")
                continue

            if key == "OR":
                or_clauses = [
                    clause for clause in ensure_list(value) if isinstance(clause, Mapping)
                ]
                if not or_clauses:
                    # Prisma: OR over an empty list matches no rows (the Python
                    # fallback in _record_matches_where already behaves this way).
                    conditions.append("1 = 0")
                    continue
                sub_conditions = []
                for clause in or_clauses:
                    sql, nested_params, idx = self._build_sql_where(
                        cast(Mapping[str, Any], clause),
                        table,
                        idx,
                    )
                    if sql:
                        sub_conditions.append(f"({sql})")
                        params.extend(nested_params)
                if sub_conditions:
                    conditions.append(f"({' OR '.join(sub_conditions)})")
                continue

            if key == "NOT":
                for clause in ensure_list(value):
                    if not isinstance(clause, Mapping):
                        continue
                    sql, nested_params, idx = self._build_sql_where(
                        cast(Mapping[str, Any], clause),
                        table,
                        idx,
                    )
                    if sql:
                        conditions.append(f"NOT ({sql})")
                        params.extend(nested_params)
                continue

            if key in self.RELATION_CONFIGS:
                sql, relation_params, idx = self._build_relation_filter_sql(key, value, idx)
                if sql:
                    conditions.append(sql)
                    params.extend(relation_params)
                continue

            if key in self.JSON_FIELDS_SET:
                sql, json_params, idx = SQLBuilder.build_json_filter(
                    key,
                    cast(Mapping[str, Any], value),
                    table,
                    idx,
                    self.FIELD_TO_COLUMN,
                )
                if sql:
                    conditions.append(sql)
                    params.extend(json_params)
                continue

            sql, scalar_params, idx = SQLBuilder.build_where(
                {key: value},
                table,
                idx,
                self.FIELD_TO_COLUMN,
                self.SCALAR_LIST_FIELDS,
            )
            if sql:
                conditions.append(sql)
                params.extend(scalar_params)

        return " AND ".join(conditions), params, idx

    def _merge_relation_filter_load_options(
        self,
        target: Dict[str, Any],
        source: Optional[Mapping[str, Any]],
    ) -> None:
        if not source:
            return

        for relation_name, incoming in dict(source).items():
            existing = target.get(relation_name)
            if isinstance(existing, Mapping) and isinstance(incoming, Mapping):
                merged = dict(existing)
                merged_include = dict(cast(Mapping[str, Any], merged.get("include") or {}))
                incoming_include = cast(Mapping[str, Any], incoming.get("include") or {})
                self._merge_relation_filter_load_options(merged_include, incoming_include)
                if merged_include:
                    merged["include"] = merged_include
                target[relation_name] = merged
                continue

            if existing is True and isinstance(incoming, Mapping):
                target[relation_name] = dict(incoming)
                continue

            if isinstance(existing, Mapping) and incoming is True:
                continue

            target[relation_name] = dict(incoming) if isinstance(incoming, Mapping) else True

    def _build_relation_filter_load_options(
        self,
        where: Optional[Mapping[str, Any]],
    ) -> Optional[Dict[str, Any]]:
        if not where:
            return None

        load_options: Dict[str, Any] = {}

        for key, value in dict(where).items():
            if key in ("AND", "OR", "NOT"):
                for clause in ensure_list(value):
                    if isinstance(clause, Mapping):
                        nested_options = self._build_relation_filter_load_options(
                            cast(Mapping[str, Any], clause)
                        )
                        self._merge_relation_filter_load_options(load_options, nested_options)
                continue

            config = self.RELATION_CONFIGS.get(key)
            if config is None:
                continue

            option: Any = True
            if isinstance(value, Mapping):
                related_delegate = self._get_delegate(cast(str, config["model"]))
                nested_loads: Dict[str, Any] = {}
                if cast(str, config["kind"]) in ("m2m", "inverse_many"):
                    for operator in ("some", "none", "every"):
                        nested_where = value.get(operator)
                        if isinstance(nested_where, Mapping):
                            self._merge_relation_filter_load_options(
                                nested_loads,
                                related_delegate._build_relation_filter_load_options(
                                    cast(Mapping[str, Any], nested_where)
                                ),
                            )
                else:
                    has_relation_operator = False
                    for operator in ("is", "isNot"):
                        if operator not in value:
                            continue
                        has_relation_operator = True
                        nested_where = value.get(operator)
                        if isinstance(nested_where, Mapping):
                            self._merge_relation_filter_load_options(
                                nested_loads,
                                related_delegate._build_relation_filter_load_options(
                                    cast(Mapping[str, Any], nested_where)
                                ),
                            )
                    if not has_relation_operator:
                        self._merge_relation_filter_load_options(
                            nested_loads,
                            related_delegate._build_relation_filter_load_options(
                                cast(Mapping[str, Any], value)
                            ),
                        )

                if nested_loads:
                    option = {"include": nested_loads}

            self._merge_relation_filter_load_options(load_options, {key: option})

        return load_options or None

    def _sql_pushdown_where(self, where: Optional[Mapping[str, Any]]) -> Optional[Dict[str, Any]]:
        """Return the SQL-expressible subset of a Python-evaluated where, as an AND.

        Used when the full filter needs Python evaluation: each top-level conjunct of
        the where (implicit AND of keys, flattened through explicit AND nodes) that is
        individually SQL-expressible is pushed to the query so fewer rows are scanned,
        and Python still applies the complete filter afterward for exactness.
        Narrowing by a subset of AND conditions can only return a superset of the final
        rows, so this is always sound. An OR or NOT node is pushed only when fully
        expressible; an OR with a Python disjunct cannot be partially pushed.
        Returns None when no conjunct is pushable (a true full-table scan).
        """
        if not where:
            return None

        conjuncts: List[Dict[str, Any]] = []

        def collect(node: Mapping[str, Any]) -> None:
            for key, value in dict(node).items():
                if key == "AND":
                    for clause in ensure_list(value):
                        if isinstance(clause, Mapping):
                            collect(cast(Mapping[str, Any], clause))
                    continue
                candidate: Dict[str, Any] = {key: value}
                if not self._where_requires_python_evaluation(candidate):
                    conjuncts.append(candidate)

        collect(where)

        if not conjuncts:
            return None
        if len(conjuncts) == 1:
            return conjuncts[0]
        return {"AND": conjuncts}

    def _where_requires_python_evaluation(
        self,
        where: Optional[Mapping[str, Any]],
    ) -> bool:
        if not where:
            return False

        for key, value in dict(where).items():
            if key in ("AND", "OR", "NOT"):
                if any(
                    self._where_requires_python_evaluation(cast(Mapping[str, Any], clause))
                    for clause in ensure_list(value)
                    if isinstance(clause, Mapping)
                ):
                    return True
                continue

            if key in self.RELATION_CONFIGS:
                if self._relation_filter_requires_python_evaluation(key, value):
                    return True
                continue

            if key in self.JSON_FIELDS_SET:
                if not SQLBuilder.can_build_json_filter(value):
                    return True
                continue

            if key in self.SCALAR_LIST_FIELDS_SET and SQLBuilder.PROVIDER != "postgresql":
                return True

        return False

    def _matches_relation_filter(
        self,
        relation_name: str,
        relation_value: Any,
        condition: Any,
    ) -> bool:
        config = self.RELATION_CONFIGS.get(relation_name)
        if config is None:
            raise ValueError(f"Unknown relation filter: {relation_name}")

        if not isinstance(condition, Mapping):
            raise ValueError(f"Relation filter '{relation_name}' expects a mapping value")

        delegate = self._get_delegate(cast(str, config["model"]))
        relation_kind = cast(str, config["kind"])

        if relation_kind in ("m2m", "inverse_many"):
            items = relation_value if isinstance(relation_value, list) else []
            for operation, expected in dict(condition).items():
                if operation not in ("some", "none", "every"):
                    raise ValueError(
                        f"Unsupported list relation filter operation '{operation}' for relation '{relation_name}'"
                    )
                if not isinstance(expected, Mapping):
                    raise ValueError(
                        f"List relation filter '{relation_name}.{operation}' expects a mapping value"
                    )

                nested_where = cast(Mapping[str, Any], expected)
                if operation == "some":
                    if not any(delegate._record_matches_where(item, nested_where) for item in items):
                        return False
                    continue
                if operation == "none":
                    if any(delegate._record_matches_where(item, nested_where) for item in items):
                        return False
                    continue
                if not all(delegate._record_matches_where(item, nested_where) for item in items):
                    return False

            return True

        if not condition:
            return relation_value is not None

        relation_operators = [
            operation for operation in dict(condition).keys() if operation in ("is", "isNot")
        ]
        if relation_operators:
            for operation, expected in dict(condition).items():
                if operation not in ("is", "isNot"):
                    raise ValueError(
                        f"Unsupported to-one relation filter operation '{operation}' for relation '{relation_name}'"
                    )

                if operation == "is":
                    if expected is None:
                        if relation_value is not None:
                            return False
                        continue
                    if not isinstance(expected, Mapping):
                        raise ValueError(
                            f"To-one relation filter '{relation_name}.is' expects a mapping value or None"
                        )
                    if relation_value is None or not delegate._record_matches_where(
                        relation_value,
                        cast(Mapping[str, Any], expected),
                    ):
                        return False
                    continue

                if expected is None:
                    if relation_value is None:
                        return False
                    continue
                if not isinstance(expected, Mapping):
                    raise ValueError(
                        f"To-one relation filter '{relation_name}.isNot' expects a mapping value or None"
                    )
                if relation_value is not None and delegate._record_matches_where(
                    relation_value,
                    cast(Mapping[str, Any], expected),
                ):
                    return False

            return True

        if relation_value is None:
            return False

        return delegate._record_matches_where(
            relation_value,
            cast(Mapping[str, Any], condition),
        )

    def _record_matches_where(self, record: Any, where: Optional[Mapping[str, Any]]) -> bool:
        if not where:
            return True

        for key, value in dict(where).items():
            if key == "AND":
                clauses = [clause for clause in ensure_list(value) if isinstance(clause, Mapping)]
                if not all(
                    self._record_matches_where(record, cast(Mapping[str, Any], clause))
                    for clause in clauses
                ):
                    return False
                continue

            if key == "OR":
                clauses = [clause for clause in ensure_list(value) if isinstance(clause, Mapping)]
                if not clauses or not any(
                    self._record_matches_where(record, cast(Mapping[str, Any], clause))
                    for clause in clauses
                ):
                    return False
                continue

            if key == "NOT":
                clauses = [clause for clause in ensure_list(value) if isinstance(clause, Mapping)]
                if any(
                    self._record_matches_where(record, cast(Mapping[str, Any], clause))
                    for clause in clauses
                ):
                    return False
                continue

            if key in self.RELATION_CONFIGS:
                if not self._matches_relation_filter(key, getattr(record, key, None), value):
                    return False
                continue

            if key in self.JSON_FIELDS_SET:
                if not matches_json_filter_value(get_source_value(record, key), value):
                    return False
                continue

            if key in self.SCALAR_LIST_FIELDS_SET:
                if not matches_scalar_list_filter_value(get_source_value(record, key), value):
                    return False
                continue

            if not matches_scalar_filter_value(get_source_value(record, key), value):
                return False

        return True

    def _record_matches_unique(self, record: Any, where: Mapping[str, Any]) -> bool:
        return all(get_source_value(record, field) == value for field, value in dict(where).items())

    def _apply_distinct_results(
        self,
        records: List[UserRole],
        distinct: Optional[List[str]] = None,
    ) -> List[UserRole]:
        if not distinct:
            return records

        seen: Set[Tuple[Any, ...]] = set()
        unique_records: List[UserRole] = []
        for record in records:
            key = tuple(get_source_value(record, field) for field in distinct)
            if key in seen:
                continue
            seen.add(key)
            unique_records.append(record)

        return unique_records

    def _apply_window_results(
        self,
        records: List[UserRole],
        cursor: Optional[UserRoleWhereUniqueInput] = None,
        skip: Optional[int] = None,
        take: Optional[int] = None,
    ) -> List[UserRole]:
        offset = skip or 0

        if take == 0:
            return []

        if cursor:
            normalized_cursor = self._normalize_unique_where(cast(Mapping[str, Any], cursor))
            cursor_index: Optional[int] = None
            for index, record in enumerate(records):
                if self._record_matches_unique(record, normalized_cursor):
                    cursor_index = index
                    break

            if cursor_index is None:
                return []

            if take is not None and take < 0:
                end_index = cursor_index + 1 - offset
                if end_index <= 0:
                    return []
                start_index = max(0, end_index + take)
                return records[start_index:end_index]

            start_index = max(0, cursor_index + offset)
            if take is None:
                return records[start_index:]
            return records[start_index:start_index + take]

        if take is not None and take < 0:
            end_index = len(records) - offset
            if end_index <= 0:
                return []
            start_index = max(0, end_index + take)
            return records[start_index:end_index]

        if offset:
            records = records[offset:]

        if take is not None:
            return records[:take]

        return records

    def _order_by_is_sql_expressible(self, order_by: Optional[Any]) -> bool:
        """True only for plain scalar asc/desc (optionally with sort/nulls) order clauses.

        Relation/aggregate ordering (e.g. _count or nested relation order) is not
        SQL-expressible here, so those force the Python fallback path.
        """
        if not order_by:
            return True
        for clause in ensure_list(order_by):
            if not isinstance(clause, Mapping):
                return False
            for field, direction in clause.items():
                if not isinstance(field, str) or field.startswith("_") or field not in self.FIELDS_SET:
                    return False
                if isinstance(direction, str):
                    continue
                if isinstance(direction, Mapping):
                    if set(direction.keys()) - {"sort", "nulls"}:
                        return False
                    continue
                return False
        return True

    async def _relation_window_pk_filter(
        self,
        base_where: Mapping[str, Any],
        fk_fields: List[str],
        nested_order: Optional[Any],
        nested_skip: Optional[int],
        nested_take: Optional[int],
    ) -> Optional[Dict[str, Any]]:
        """Push a per-parent take/skip window into SQL for a to-many include.

        Returns a primary-key where fragment selecting exactly the windowed child
        rows (one window per parent via ROW_NUMBER), an empty dict when the window
        matches nothing, or None to signal the caller to keep the existing
        fetch-all + Python window path. Only simple, fully SQL-expressible cases are
        pushed down; everything else falls back so behavior is unchanged.
        """
        if SQLBuilder.PROVIDER == "mysql" and not get_db_capabilities().supports_window_functions:
            return None  # ROW_NUMBER needs MySQL 8.0+ / MariaDB 10.2+; older servers keep the Python window

        offset = int(nested_skip) if nested_skip else 0
        take_limit = int(nested_take) if nested_take is not None else None
        if offset < 0:
            return None
        if take_limit is not None and take_limit < 0:
            return None  # negative take (last N) stays in Python
        if take_limit is None and not offset:
            return None  # nothing to window
        if not self.PK_FIELDS or not fk_fields:
            return None
        if self._where_requires_python_evaluation(base_where):
            return None
        if not self._order_by_is_sql_expressible(nested_order):
            return None

        where_sql, where_params, _ = self._build_sql_where(dict(base_where), "", 0)

        pk_columns = [self._db_column(f) for f in self.PK_FIELDS]
        fk_columns = [self._db_column(f) for f in fk_fields]
        select_cols = ", ".join(SQLBuilder.quote_identifier(c) for c in pk_columns)
        partition_sql = ", ".join(SQLBuilder.quote_identifier(c) for c in fk_columns)
        order_sql = (
            SQLBuilder.build_order_by(nested_order, field_map=self.FIELD_TO_COLUMN)
            if nested_order
            else ""
        )
        if not order_sql:
            order_sql = "ORDER BY " + ", ".join(SQLBuilder.quote_identifier(c) for c in pk_columns)

        inner = (
            f"SELECT {select_cols}, "
            f"ROW_NUMBER() OVER (PARTITION BY {partition_sql} {order_sql}) AS _pp_rn "
            f"FROM {SQLBuilder.quote_identifier(self.TABLE)}"
        )
        if where_sql:
            inner += f" WHERE {where_sql}"

        sql = f"SELECT {select_cols} FROM ({inner}) AS _pp_win WHERE _pp_rn > {offset}"
        if take_limit is not None:
            sql += f" AND _pp_rn <= {offset + take_limit}"

        conn = await self._get_conn()
        rows = await fetch_dict_rows(conn, sql, where_params, list(self.PK_FIELDS))
        if not rows:
            return {}

        # The hydrate step binds one (or one-per-PK-column) placeholder per windowed row.
        # If that would exceed the variable limit, fall back to the bounded fetch-all +
        # Python window path instead of emitting an oversized IN/OR list.
        if len(rows) * max(1, len(self.PK_FIELDS)) > _MAX_SQL_VARS:
            return None

        if len(self.PK_FIELDS) == 1:
            field = self.PK_FIELDS[0]
            column = self._db_column(field)
            return {field: {"in_": [row.get(column) for row in rows]}}

        conditions: List[Dict[str, Any]] = []
        for row in rows:
            conditions.append({field: row.get(self._db_column(field)) for field in self.PK_FIELDS})
        return {"OR": conditions}

    async def _load_relation_counts(
        self,
        records: List[UserRole],
        count_requests: Dict[str, Any],
    ) -> None:
        if not records or not count_requests:
            return

        if len(records) > _MAX_SQL_VARS:
            # Chunk parents so a single grouped-count query never binds more than
            # _MAX_SQL_VARS placeholders. Batches are disjoint parent sets, so each
            # writes counts onto its own records.
            for _batch in _chunk(records):
                await self._load_relation_counts(_batch, count_requests)
            return

        conn = await self._get_conn()  # noqa: F841 -- used only by generated count strategies
        handled_count_requests: Set[str] = set()

        _count_option_user = count_requests.get("user")
        _count_where_user: Optional[Mapping[str, Any]] = None
        _count_pushdown_user = _count_option_user is True
        if (
            isinstance(_count_option_user, Mapping)
            and set(_count_option_user.keys()) <= {"where"}
        ):
            _raw_count_where_user = _count_option_user.get("where")
            if _raw_count_where_user is None:
                _count_pushdown_user = True
            elif isinstance(_raw_count_where_user, Mapping):
                # Filtered relation counts push the child filter into the grouped
                # COUNT query instead of hydrating every child row just to len() it.
                delegate = self._get_delegate("User")
                if not delegate._where_requires_python_evaluation(_raw_count_where_user):
                    _count_where_user = cast(Mapping[str, Any], _raw_count_where_user)
                    _count_pushdown_user = True
        if _count_pushdown_user:
            local_ids = [
                getattr(record, "id")
                for record in records
                if getattr(record, "id", None) is not None
            ]
            unique_local_ids = list(dict.fromkeys(local_ids))
            delegate = self._get_delegate("User")
            _count_extra_sql_user = ""
            _count_extra_params_user: List[Any] = []
            if _count_where_user is not None:
                _count_extra_sql_user, _count_extra_params_user, _ = delegate._build_sql_where(
                    dict(_count_where_user), "", len(unique_local_ids)
                )
            grouped_counts = await fetch_grouped_count_rows(
                conn,
                delegate.TABLE,
                delegate._db_column("roleId"),
                unique_local_ids,
                _count_extra_sql_user,
                _count_extra_params_user,
            )
            for record in records:
                local_id = getattr(record, "id", None)
                count_data = dict(record._count or {})
                count_data["user"] = grouped_counts.get(local_id, 0) if local_id is not None else 0
                record._count = count_data
            handled_count_requests.add("user")

        remaining_count_requests = {
            relation_name: option
            for relation_name, option in count_requests.items()
            if relation_name not in handled_count_requests
        }
        if not remaining_count_requests:
            return

        count_include = {relation_name: option for relation_name, option in remaining_count_requests.items()}
        await self._load_relations(records, cast(Any, count_include))

        for record in records:
            count_data = dict(record._count or {})
            for relation_name in remaining_count_requests.keys():
                relation_value = getattr(record, relation_name, None)
                if isinstance(relation_value, list):
                    count_data[relation_name] = len(relation_value)
                else:
                    count_data[relation_name] = 1 if relation_value is not None else 0
            record._count = count_data

    def _generate_defaults(self, data_dict: Dict[str, Any]) -> Dict[str, Any]:
        """Generate default values for ID and timestamp fields"""
        return data_dict

    async def _load_relations(
        self,
        records: List[UserRole],
        include: Optional[UserRoleInclude] = None,
    ) -> None:
        """Load relations for records based on include dict"""
        if not include or not records:
            return

        if len(records) > _MAX_SQL_VARS:
            # Chunk parents so the IN / OR / join lists built per relation never bind
            # more than _MAX_SQL_VARS placeholders. Batches are disjoint parent sets,
            # so each batch loads relations onto its own records independently.
            for _batch in _chunk(records):
                await self._load_relations(_batch, include)
            return

        conn = await self._get_conn()  # noqa: F841 -- used only by generated relation strategies

        # Load user relation
        inc_user = include.get("user")
        if inc_user:
            delegate = self._get_delegate("User")
            nested_include = None
            nested_select = None
            nested_omit = None
            nested_where = None
            nested_order = None
            nested_take = None
            nested_skip = None
            nested_distinct = None
            nested_cursor = None

            if isinstance(inc_user, dict):
                nested_include = inc_user.get("include")
                nested_select = inc_user.get("select")
                nested_omit = inc_user.get("omit")
                nested_where = inc_user.get("where")
                nested_order = inc_user.get("orderBy")  # noqa: F841 -- relation-shape dependent
                nested_take = inc_user.get("take")  # noqa: F841 -- relation-shape dependent
                nested_skip = inc_user.get("skip")  # noqa: F841 -- relation-shape dependent
                nested_distinct = inc_user.get("distinct")
                nested_cursor = inc_user.get("cursor")

            local_keys = [
                key
                for key in (
                    self._identity_for_fields(record, ["id"])
                    for record in records
                )
                if key is not None
            ]
            unique_local_keys = list(dict.fromkeys(local_keys))

            if unique_local_keys:
                if len(unique_local_keys[0]) == 1:
                    base_where: Dict[str, Any] = {
                        "roleId": {"in_": [key_values[0] for key_values in unique_local_keys]}
                    }
                else:
                    base_conditions: List[Dict[str, Any]] = []
                    for key_values in unique_local_keys:
                        condition = {
                            "roleId": key_values[0],
                        }
                        base_conditions.append(condition)

                    base_where = {"OR": base_conditions}
                if nested_where:
                    base_where = {"AND": [base_where, nested_where]}

                # Push the per-parent take/skip window into SQL when possible so we only
                # fetch the rows each parent actually keeps, instead of every child row.
                window_pk_where: Optional[Dict[str, Any]] = None
                if (nested_take is not None or nested_skip) and not nested_cursor and not nested_distinct:
                    window_pk_where = await delegate._relation_window_pk_filter(
                        base_where,
                        ["roleId"],
                        nested_order,
                        nested_skip,
                        nested_take,
                    )

                related_select = augment_relation_select(nested_select, ["roleId"])
                window_applied = False
                if window_pk_where is not None and not window_pk_where:
                    related = []
                    window_applied = True
                elif window_pk_where is not None:
                    related = await delegate.find_many(
                        where=window_pk_where,
                        select=related_select,
                        omit=nested_omit,
                        include=nested_include,
                        order_by=nested_order,
                    )
                    window_applied = True
                else:
                    related = await delegate.find_many(
                        where=base_where,
                        select=related_select,
                        omit=nested_omit,
                        include=nested_include,
                        order_by=nested_order,
                    )
                restore_relation_select(related, nested_select)

                by_key: Dict[Tuple[Any, ...], Any] = {}
                for rel_rec in related:
                    rel_key = delegate._identity_for_fields(
                        rel_rec,
                        ["roleId"],
                    )
                    if rel_key is None:
                        continue
                    by_key.setdefault(rel_key, []).append(rel_rec)

                for rec in records:
                    local_key = self._identity_for_fields(
                        rec,
                        ["id"],
                    )
                    items = by_key.get(local_key, []) if local_key is not None else []
                    if nested_distinct:
                        items = delegate._apply_distinct_results(items, nested_distinct)
                    if not window_applied and (nested_cursor or nested_skip or nested_take is not None):
                        items = delegate._apply_window_results(
                            items,
                            nested_cursor,
                            nested_skip,
                            nested_take,
                        )
                    rec.user = items

    async def find_many(
        self,
        where: Optional[UserRoleWhereInput] = None,
        select: Optional[UserRoleSelect] = None,
        omit: Optional[UserRoleOmit] = None,
        include: Optional[UserRoleInclude] = None,
        order_by: Optional[Union[List[UserRoleOrderBy], UserRoleOrderBy]] = None,
        skip: Optional[int] = None,
        take: Optional[int] = None,
        distinct: Optional[List[str]] = None,
        cursor: Optional[UserRoleWhereUniqueInput] = None,
    ) -> List[UserRole]:
        """Find multiple records with include support"""
        validate_projection_options(select, omit, include)
        conn = await self._get_conn()

        select_dict: Optional[SelectDict] = cast(SelectDict, select) if select else None
        omit_dict: Optional[SelectDict] = cast(SelectDict, omit) if omit else None
        relation_load_options = self._build_relation_load_options(select, include)
        where_requires_python_evaluation = self._where_requires_python_evaluation(where)
        relation_filter_load_options = (
            self._build_relation_filter_load_options(where)
            if where_requires_python_evaluation
            else None
        )
        count_requests = self._extract_count_requests(select, include)
        needs_full_row = bool(
            where_requires_python_evaluation
            or relation_load_options
            or relation_filter_load_options
            or count_requests
        )
        cols_sql, selected_fields = self._build_row_select(
            select_dict,
            omit_dict,
            needs_full_row,
            can_narrow=not where_requires_python_evaluation and not relation_filter_load_options,
        )

        sql = f'SELECT {cols_sql} FROM {SQLBuilder.quote_identifier(self.TABLE)}'

        params: List[Any] = []
        param_idx = 0
        has_where_clause = False

        if where and not where_requires_python_evaluation:
            where_sql, where_params, param_idx = self._build_sql_where(dict(where), "", param_idx)
            if where_sql:
                sql += f" WHERE {where_sql}"
                params.extend(where_params)
                has_where_clause = True
        elif where and where_requires_python_evaluation:
            # The full filter is not SQL-expressible, but we can still push down the
            # SQL-expressible conjuncts so the database returns fewer rows; Python then
            # applies the complete filter below for exactness. Only a where with no
            # pushable conjunct degrades to an actual full-table scan.
            partial_where = self._sql_pushdown_where(where)
            if partial_where:
                where_sql, where_params, param_idx = self._build_sql_where(dict(partial_where), "", param_idx)
                if where_sql:
                    sql += f" WHERE {where_sql}"
                    params.extend(where_params)
                    has_where_clause = True
            else:
                _warn_full_scan("UserRole", "where filter: " + ", ".join(sorted(str(k) for k in dict(where).keys())))

        # SQL-side cursor window: anchor the query at the cursor row with a
        # lexicographic order comparison so only the requested page is fetched,
        # instead of scanning every matching row to locate the cursor in Python.
        # Requires an explicit SQL-expressible order_by; other shapes keep the
        # Python windowing path below.
        cursor_plan: Optional[Dict[str, Any]] = None
        if (
            cursor is not None
            and order_by
            and not distinct
            and not where_requires_python_evaluation
        ):
            cursor_plan = await self._build_cursor_window_plan(cursor, order_by, take, skip)
            if cursor_plan is not None and cursor_plan.get("empty"):
                return []

        if cursor_plan is not None:
            comparison_clauses = cast(List[Tuple[str, bool]], cursor_plan["comparison_clauses"])
            comparison_sql, comparison_params, param_idx = self._build_cursor_comparison_sql(
                comparison_clauses,
                cast(List[Any], cursor_plan["cursor_values"]),
                param_idx,
            )
            sql += (" AND " if has_where_clause else " WHERE ") + comparison_sql
            params.extend(comparison_params)
            order_parts = [
                f"{SQLBuilder.column_ref(self._db_column(field))} {'DESC' if descending else 'ASC'}"
                for field, descending in comparison_clauses
            ]
            sql += " ORDER BY " + ", ".join(order_parts)
        elif order_by:
            if not self._order_by_is_sql_expressible(order_by):
                # Prisma supports relation-field and relation-_count ordering; this
                # client does not yet. Raise instead of emitting broken SQL that
                # references the relation name as a column.
                raise PrismaClientValidationError(
                    "Unsupported order_by: only scalar model fields ordered "
                    "asc/desc (optionally with {sort, nulls}) are supported; "
                    "relation and aggregate ordering are not implemented."
                )
            sql += " " + SQLBuilder.build_order_by(order_by, field_map=self.FIELD_TO_COLUMN)

        apply_sql_window = (
            cursor_plan is None
            and not where_requires_python_evaluation
            and cursor is None
            and not distinct
            and (take is None or take >= 0)
        )
        if cursor_plan is not None:
            plan_take = cast(Optional[int], cursor_plan["take"])
            plan_offset = cast(int, cursor_plan["offset"])
            plan_limit = abs(plan_take) if plan_take is not None else None
            if plan_limit is not None:
                sql += f" LIMIT {plan_limit}"
            elif plan_offset:
                if SQLBuilder.PROVIDER == "sqlite":
                    sql += " LIMIT -1"
                elif SQLBuilder.PROVIDER == "mysql":
                    sql += " LIMIT 18446744073709551615"
            if plan_offset:
                sql += f" OFFSET {plan_offset}"
        elif apply_sql_window and take is not None:
            sql += f" LIMIT {int(take)}"
        elif apply_sql_window and skip:
            # SQLite/MySQL reject OFFSET without LIMIT; emit the provider's
            # "unbounded" limit so skip-only queries stay valid SQL.
            if SQLBuilder.PROVIDER == "sqlite":
                sql += " LIMIT -1"
            elif SQLBuilder.PROVIDER == "mysql":
                sql += " LIMIT 18446744073709551615"
        if apply_sql_window and skip:
            sql += f" OFFSET {int(skip)}"

        rows = await fetch_dict_rows(conn, sql, params, selected_fields)
        results = [self._row_to_model(row, selected_fields) for row in rows]
        if cursor_plan is not None and cast(bool, cursor_plan["reverse"]):
            # Negative take fetched in reversed order; restore the requested order.
            results.reverse()

        if where_requires_python_evaluation:
            if relation_filter_load_options:
                await self._load_relations(results, cast(Any, relation_filter_load_options))
            results = [
                record
                for record in results
                if self._record_matches_where(record, cast(Mapping[str, Any], where))
            ]

        if distinct:
            results = self._apply_distinct_results(results, distinct)

        if not apply_sql_window and cursor_plan is None:
            results = self._apply_window_results(results, cursor, skip, take)

        # Apply query options and load relations
        for rec in results:
            self._apply_query_options(rec, select, omit, include)

        if relation_load_options:
            await self._load_relations(results, cast(Any, relation_load_options))

        if count_requests:
            await self._load_relation_counts(results, count_requests)

        return results

    async def find_unique(
        self,
        where: UserRoleWhereUniqueInput,
        select: Optional[UserRoleSelect] = None,
        omit: Optional[UserRoleOmit] = None,
        include: Optional[UserRoleInclude] = None,
    ) -> Optional[UserRole]:
        """Find unique record with include support"""
        validate_projection_options(select, omit, include)
        conn = await self._get_conn()

        select_dict: Optional[SelectDict] = cast(SelectDict, select) if select else None
        omit_dict: Optional[SelectDict] = cast(SelectDict, omit) if omit else None
        relation_load_options = self._build_relation_load_options(select, include)
        count_requests = self._extract_count_requests(select, include)
        needs_full_row = bool(relation_load_options or count_requests)
        cols_sql, selected_fields = self._build_row_select(
            select_dict,
            omit_dict,
            needs_full_row,
            can_narrow=True,
        )
        sql = f'SELECT {cols_sql} FROM {SQLBuilder.quote_identifier(self.TABLE)}'

        normalized_where = self._normalize_unique_where(where)
        where_sql, params, _ = SQLBuilder.build_where(
            normalized_where,
            field_map=self.FIELD_TO_COLUMN,
            scalar_list_fields=self.SCALAR_LIST_FIELDS,
        )
        if where_sql:
            sql += f" WHERE {where_sql}"
        sql += " LIMIT 1"

        row = await fetch_dict_row(conn, sql, params, selected_fields)
        if not row:
            return None

        result = self._row_to_model(row, selected_fields)
        self._apply_query_options(result, select, omit, include)

        if relation_load_options:
            await self._load_relations([result], cast(Any, relation_load_options))

        if count_requests:
            await self._load_relation_counts([result], count_requests)

        return result

    async def find_unique_or_throw(
        self,
        where: UserRoleWhereUniqueInput,
        select: Optional[UserRoleSelect] = None,
        omit: Optional[UserRoleOmit] = None,
        include: Optional[UserRoleInclude] = None,
    ) -> UserRole:
        """Find unique or raise error"""
        result = await self.find_unique(where, select, omit, include)
        if result is None:
            raise RecordNotFoundError(f"UserRole not found: {where}")
        return result

    async def find_first(
        self,
        where: Optional[UserRoleWhereInput] = None,
        select: Optional[UserRoleSelect] = None,
        omit: Optional[UserRoleOmit] = None,
        include: Optional[UserRoleInclude] = None,
        order_by: Optional[Union[List[UserRoleOrderBy], UserRoleOrderBy]] = None,
        skip: Optional[int] = None,
        distinct: Optional[List[str]] = None,
        cursor: Optional[UserRoleWhereUniqueInput] = None,
    ) -> Optional[UserRole]:
        """Find first matching record"""
        results = await self.find_many(
            where=where, select=select, omit=omit, include=include,
            order_by=order_by, skip=skip, take=1, distinct=distinct, cursor=cursor
        )
        return results[0] if results else None

    async def find_first_or_throw(
        self,
        where: Optional[UserRoleWhereInput] = None,
        select: Optional[UserRoleSelect] = None,
        omit: Optional[UserRoleOmit] = None,
        include: Optional[UserRoleInclude] = None,
        order_by: Optional[Union[List[UserRoleOrderBy], UserRoleOrderBy]] = None,
        skip: Optional[int] = None,
    ) -> UserRole:
        """Find first or raise error"""
        result = await self.find_first(where, select, omit, include, order_by, skip)
        if result is None:
            raise RecordNotFoundError("UserRole not found")
        return result

    async def create(
        self,
        data: UserRoleCreateInput,
        select: Optional[UserRoleSelect] = None,
        omit: Optional[UserRoleOmit] = None,
        include: Optional[UserRoleInclude] = None,
    ) -> UserRole:
        """Create a new record"""
        validate_projection_options(select, omit, include)
        conn = await self._get_conn()

        data_dict = dict(data)
        relation_writes = self._extract_relation_writes(data_dict)
        if relation_writes and not self._is_in_transaction():
            async with self._transaction_scope():
                return await self.create(data, select=select, omit=omit, include=include)

        await self._apply_pre_write_relations(data_dict, relation_writes)
        data_dict = self._prepare_create_data(data_dict)

        fields = [field for field in self.FIELDS if field in data_dict]
        db_fields = [self._db_column(field) for field in fields]
        values = [data_dict[k] for k in fields]
        pk_field = self.PK_FIELDS[0] if len(self.PK_FIELDS) == 1 else None
        pk_value = data_dict.get(pk_field) if pk_field else None
        db_pk_field = self._db_column(pk_field) if pk_field else None

        supports_create_returning = (
            SQLBuilder.PROVIDER in ("postgresql", "sqlite")
            or get_db_capabilities().supports_insert_returning
        )
        if supports_create_returning and fields:
            # PostgreSQL, SQLite 3.35+, and MariaDB 10.5+: hydrate the created row
            # straight from INSERT ... RETURNING, saving the extra SELECT
            # round-trip the lastrowid path needs below.
            returning_sql, selected_fields = SQLBuilder.build_select(
                self.TABLE,
                self.FIELDS,
                None,
                None,
                field_map=self.FIELD_TO_COLUMN,
            )
            returned_rows = await execute_bulk_insert_returning(
                conn,
                self.TABLE,
                db_fields,
                [tuple(values)],
                returning_sql,
                False,
                self._commit_if_needed,
            )
            if not returned_rows:
                raise RecordNotFoundError("Failed to create UserRole")
            stored_record = self._row_to_model(returned_rows[0], selected_fields)
        else:
            pk_value = await execute_insert_query(
                conn,
                self.TABLE,
                db_fields,
                values,
                db_pk_field,
                pk_value,
                self._commit_if_needed,
            )

            if pk_field is not None and pk_value is not None:
                data_dict[pk_field] = pk_value

            created_where = cast(UserRoleWhereUniqueInput, self._build_primary_where(data_dict))
            stored_record = await self.find_unique(created_where)
            if stored_record is None:
                raise RecordNotFoundError("Failed to create UserRole")

        created_where = cast(UserRoleWhereUniqueInput, self._build_primary_where(stored_record))
        await self._apply_post_write_relations(stored_record, relation_writes)
        if not (select or omit or include):
            return stored_record

        # Scalar-only projections need no relation loads, so the freshly
        # hydrated row can be projected in place without another SELECT.
        relation_load_options = self._build_relation_load_options(select, include)
        count_requests = self._extract_count_requests(select, include)
        if not relation_load_options and not count_requests:
            return self._apply_query_options(stored_record, select, omit, include)

        result = await self.find_unique(created_where, select=select, omit=omit, include=include)
        if result is None:
            raise RecordNotFoundError("Failed to load UserRole after create")
        return result

    async def create_many(
        self,
        data: List[UserRoleCreateInput],
        skip_duplicates: bool = False,
    ) -> Dict[str, int]:
        """Create multiple records using batch insert"""
        if not data:
            return {"count": 0}

        conn = await self._get_conn()

        prepared_rows: List[Dict[str, Any]] = []
        for item in data:
            row = dict(item)
            row = self._generate_defaults(row)
            row = self._prepare_create_data(row)
            prepared_rows.append(row)

        if not prepared_rows:
            return {"count": 0}

        rows_by_shape: Dict[Tuple[str, ...], List[Dict[str, Any]]] = {}
        for row in prepared_rows:
            shape = tuple(field for field in self.FIELDS if field in row)
            rows_by_shape.setdefault(shape, []).append(row)

        count = 0
        for field_shape, rows_for_shape in rows_by_shape.items():
            fields = list(field_shape)
            db_fields = [self._db_column(field) for field in fields]
            values_list = [tuple(row.get(f) for f in fields) for row in rows_for_shape]
            count += await execute_bulk_insert_count(
                conn,
                self.TABLE,
                db_fields,
                values_list,
                skip_duplicates,
            )

        await self._commit_if_needed(conn)
        return {"count": count}

    async def create_many_and_return(
        self,
        data: Union[List[UserRoleCreateInput], UserRoleCreateInput],
        select: Optional[UserRoleSelect] = None,
        omit: Optional[UserRoleOmit] = None,
        include: Optional[UserRoleInclude] = None,
        skip_duplicates: bool = False,
    ) -> List[UserRole]:
        """Create multiple records and return the stored rows"""
        validate_projection_options(select, omit, include)
        if SQLBuilder.PROVIDER == "mysql":
            raise NotImplementedError(
                "Prisma createManyAndReturn is not supported by the MySQL connector. "
                "Use create_many, or explicit create calls inside a transaction when "
                "returned rows are required."
            )
        if SQLBuilder.PROVIDER == "sqlite" and skip_duplicates:
            raise NotImplementedError(
                "Prisma createManyAndReturn does not support skipDuplicates on SQLite."
            )

        raw_items = ensure_list(data)
        if not raw_items:
            return []

        for item in raw_items:
            if not isinstance(item, Mapping):
                raise ValueError("create_many_and_return expects mapping payloads")

        has_relation_writes = any(
            key in self.RELATION_CONFIGS
            for item in raw_items
            for key in cast(Mapping[str, Any], item).keys()
        )
        if has_relation_writes:
            raise PrismaClientValidationError(
                "Nested relation writes are not supported in createManyAndReturn."
            )

        prepared_rows: List[Dict[str, Any]] = []
        for item in raw_items:
            row = self._generate_defaults(dict(cast(Mapping[str, Any], item)))
            row = self._prepare_create_data(row)
            prepared_rows.append(row)

        field_shapes = [
            tuple(key for key in row.keys() if key in self.FIELDS_SET)
            for row in prepared_rows
        ]
        can_use_bulk_return = bool(field_shapes) and all(bool(shape) for shape in field_shapes)

        if can_use_bulk_return:
            conn = await self._get_conn()
            returning_sql, selected_fields = SQLBuilder.build_select(
                self.TABLE,
                self.FIELDS,
                cast(Optional[SelectDict], select),
                cast(Optional[SelectDict], omit),
                field_map=self.FIELD_TO_COLUMN,
            )
            rows: List[Any] = []
            rows_by_shape: Dict[Tuple[str, ...], List[Dict[str, Any]]] = {}
            for shape, row in zip(field_shapes, prepared_rows):
                rows_by_shape.setdefault(shape, []).append(row)

            async with self._transaction_scope():
                for shape, shaped_rows in rows_by_shape.items():
                    fields = list(shape)
                    db_fields = [self._db_column(field) for field in fields]
                    values_list = [
                        tuple(row.get(field) for field in fields)
                        for row in shaped_rows
                    ]
                    rows.extend(
                        await execute_bulk_insert_returning(
                            conn,
                            self.TABLE,
                            db_fields,
                            values_list,
                            returning_sql,
                            skip_duplicates,
                            self._commit_if_needed,
                        )
                    )

            results = [
                self._apply_query_options(
                    self._row_to_model(row, selected_fields),
                    select=select,
                    omit=omit,
                    include=include,
                )
                for row in rows
            ]
            if include:
                relation_load_options = self._build_relation_load_options(None, include)
                if relation_load_options:
                    await self._load_relations(results, cast(Any, relation_load_options))
            return results

        created_records: List[UserRole] = []
        for item in raw_items:
            created_records.append(
                await self.create(
                    cast(UserRoleCreateInput, dict(item)),
                    select=select,
                    omit=omit,
                    include=include,
                )
            )

        return created_records

    async def _find_relation_records_for_write(
        self,
        delegate: Any,
        relation_name: str,
        config: Dict[str, Any],
        record: Any,
        where: Optional[Mapping[str, Any]] = None,
    ) -> List[Any]:
        kind = cast(str, config["kind"])
        if kind == "m2m":
            local_value = get_source_value(record, cast(str, config["local_pk_field"]))
            if local_value is None:
                return []

            # Read the linked ids straight from the join table instead of
            # hydrating every related row through an include only to re-query
            # the same rows with the caller's filter.
            conn = await self._get_conn()
            remote_column = cast(str, config["remote_column"])
            join_sql = (
                f'SELECT {SQLBuilder.quote_identifier(remote_column)} '
                f'FROM {SQLBuilder.quote_identifier(cast(str, config["join_table"]))} '
                f'WHERE {SQLBuilder.quote_identifier(cast(str, config["local_column"]))} = {SQLBuilder.placeholder(0)}'
            )
            join_rows = await fetch_dict_rows(conn, join_sql, [local_value], [remote_column])
            remote_ids = [
                row.get(remote_column)
                for row in join_rows
                if row.get(remote_column) is not None
            ]
            if not remote_ids:
                return []

            remote_pk_field = cast(str, config["remote_pk_field"])
            related_results: List[Any] = []
            for _id_chunk in _chunk(list(dict.fromkeys(remote_ids))):
                combined_where = self._combine_where_clauses(
                    {remote_pk_field: {"in_": _id_chunk}},
                    where,
                )
                if combined_where is None:
                    continue
                related_results.extend(await delegate.find_many(where=combined_where))
            return related_results

        combined_where = self._combine_where_clauses(
            self._build_inverse_parent_where(config, record),
            where,
        )
        if combined_where is None:
            return []
        return await delegate.find_many(where=combined_where)

    async def _apply_pre_write_relations(
        self,
        data_dict: Dict[str, Any],
        relation_writes: Dict[str, Dict[str, Any]],
        existing_record: Optional[Any] = None,
    ) -> None:
        for relation_name, write in relation_writes.items():
            config = self.RELATION_CONFIGS.get(relation_name)
            if not config or cast(str, config["kind"]) != "owned":
                continue

            delegate = self._get_delegate(cast(str, config["model"]))
            local_fields = cast(List[str], config["local_fields"])
            remote_fields = cast(List[str], config["remote_fields"])
            current_related = (
                await self._find_owned_related_record(delegate, config, existing_record)
                if existing_record is not None
                else None
            )

            if write.get("disconnect") is True or (
                "set" in write and write["set"] in (None, [])
            ):
                if not cast(bool, config.get("can_disconnect", False)):
                    raise ValueError(f"Relation '{relation_name}' does not support disconnect")
                for field in local_fields:
                    data_dict[field] = None
                current_related = None

            if write.get("delete"):
                if not cast(bool, config.get("can_disconnect", False)):
                    raise ValueError(f"Relation '{relation_name}' does not support delete")
                if current_related is not None:
                    await delegate.delete(delegate._build_primary_where(current_related))
                for field in local_fields:
                    data_dict[field] = None
                current_related = None

            related_records: List[Any] = []
            if "set" in write and write["set"] not in (None, []):
                related_records = await self._resolve_relation_records(
                    delegate,
                    write["set"],
                    relation_name,
                )
            if "connect" in write:
                related_records = await self._resolve_relation_records(
                    delegate,
                    write["connect"],
                    relation_name,
                )
            if "create" in write:
                related_records = await self._create_relation_records(
                    delegate,
                    write["create"],
                    relation_name,
                )
            if "connectOrCreate" in write:
                related_records = await self._connect_or_create_relation_records(
                    delegate,
                    write["connectOrCreate"],
                    relation_name,
                )

            if "update" in write:
                update_entries = self._normalize_nested_entries(write["update"], relation_name)
                if len(update_entries) > 1:
                    raise ValueError(f"Relation '{relation_name}' only accepts a single update payload")
                if current_related is None:
                    raise RecordNotFoundError(
                        f"Related record for '{relation_name}' was not found for nested update"
                    )

                update_entry = update_entries[0]
                raw_update_data = update_entry.get("data")
                if isinstance(raw_update_data, Mapping):
                    update_data = dict(raw_update_data)
                else:
                    update_data = dict(update_entry)
                current_related = await delegate.update(
                    delegate._build_primary_where(current_related),
                    cast(Dict[str, Any], update_data),
                )
                if current_related is None:
                    raise RecordNotFoundError(
                        f"Failed to update related record for '{relation_name}'"
                    )
                related_records = [current_related]

            if "upsert" in write:
                upsert_entries = self._normalize_nested_entries(write["upsert"], relation_name)
                if len(upsert_entries) > 1:
                    raise ValueError(f"Relation '{relation_name}' only accepts a single upsert payload")

                upsert_entry = upsert_entries[0]
                raw_update_data = upsert_entry.get("update")
                raw_create_data = upsert_entry.get("create")
                if current_related is not None:
                    update_data = dict(raw_update_data) if isinstance(raw_update_data, Mapping) else {}
                    current_related = await delegate.update(
                        delegate._build_primary_where(current_related),
                        cast(Dict[str, Any], update_data),
                    )
                    if current_related is None:
                        raise RecordNotFoundError(
                            f"Failed to upsert related record for '{relation_name}'"
                        )
                    related_records = [current_related]
                else:
                    if not isinstance(raw_create_data, Mapping):
                        raise ValueError(
                            f"Relation '{relation_name}' requires a mapping create payload for upsert"
                        )
                    related_records = await self._create_relation_records(
                        delegate,
                        cast(Dict[str, Any], dict(raw_create_data)),
                        relation_name,
                    )

            self._ensure_singular_relation_write(relation_name, related_records)
            if related_records:
                self._apply_relation_values(
                    data_dict,
                    local_fields,
                    related_records[0],
                    remote_fields,
                )

    async def _apply_post_write_relations(
        self,
        record: Any,
        relation_writes: Dict[str, Dict[str, Any]],
    ) -> None:
        for relation_name, write in relation_writes.items():
            config = self.RELATION_CONFIGS.get(relation_name)
            if not config:
                continue

            relation_config = config
            kind = cast(str, relation_config["kind"])
            if kind == "owned":
                continue

            delegate = self._get_delegate(cast(str, relation_config["model"]))

            if kind == "m2m":
                local_pk_field = cast(str, config["local_pk_field"])
                remote_pk_field = cast(str, config["remote_pk_field"])
                join_table = cast(str, config["join_table"])
                local_column = cast(str, config["local_column"])
                remote_column = cast(str, config["remote_column"])
                local_value = get_source_value(record, local_pk_field)

                if local_value is None:
                    continue

                if "set" in write:
                    await self._clear_m2m_pairs(join_table, local_column, local_value)
                    if write["set"] not in (None, []):
                        set_records = await self._resolve_relation_records(
                            delegate,
                            write["set"],
                            relation_name,
                        )
                        set_pairs = [
                            (local_value, get_source_value(related_record, remote_pk_field))
                            for related_record in set_records
                            if get_source_value(related_record, remote_pk_field) is not None
                        ]
                        await self._connect_m2m_pairs(
                            join_table,
                            local_column,
                            remote_column,
                            set_pairs,
                        )

                create_records = []
                if "create" in write:
                    create_records = await self._create_relation_records(
                        delegate,
                        write["create"],
                        relation_name,
                    )

                connect_records = []
                if "connect" in write:
                    connect_records = await self._resolve_relation_records(
                        delegate,
                        write["connect"],
                        relation_name,
                    )

                connect_or_create_records = []
                if "connectOrCreate" in write:
                    connect_or_create_records = await self._connect_or_create_relation_records(
                        delegate,
                        write["connectOrCreate"],
                        relation_name,
                    )

                connect_pairs = [
                    (local_value, get_source_value(related_record, remote_pk_field))
                    for related_record in create_records + connect_records + connect_or_create_records
                    if get_source_value(related_record, remote_pk_field) is not None
                ]
                await self._connect_m2m_pairs(
                    join_table,
                    local_column,
                    remote_column,
                    connect_pairs,
                )

                if "update" in write:
                    update_entries = self._normalize_nested_entries(write["update"], relation_name)
                    for update_entry in update_entries:
                        where_clause = update_entry.get("where")
                        data_clause = update_entry.get("data")
                        if not isinstance(where_clause, Mapping) or not isinstance(data_clause, Mapping):
                            raise ValueError(
                                f"Relation '{relation_name}' update expects 'where' and 'data' mappings"
                            )

                        target_records = await self._find_relation_records_for_write(
                            delegate,
                            relation_name,
                            config,
                            record,
                            cast(Mapping[str, Any], where_clause),
                        )
